window.KS4SRC["model-of-the-atom"] = {"common_mistake": "In Rutherford's experiment, MOST particles passed STRAIGHT THROUGH \u2014 this is what shows atoms are mostly empty space. Only a FEW bounced back. Students often get this backwards and say most particles bounced back. The few that did bounce back were what proved the nucleus exists.", "key_note": "Dalton: solid sphere. Thomson: plum pudding (electrons in positive mass). Rutherford: nuclear model \u2014 most particles pass through (empty space), a few bounce back (dense positive nucleus). Bohr: electrons in fixed shells. Each model revised due to new experimental evidence.", "matching": {"instruction": "Match each atomic model to the scientist and what evidence led to it.", "pairs": [["Dalton", "Solid indivisible sphere \u2014 no subatomic particles known at this time"], ["Thomson", "Plum pudding \u2014 discovery of the electron showed atoms had internal structure"], ["Rutherford", "Nuclear model \u2014 gold foil experiment showed a tiny dense positive nucleus"], ["Bohr", "Shell model \u2014 electrons orbit in fixed energy levels around the nucleus"]], "title": "Match the Model to its Scientist and Evidence"}, "quiz": {"CF": [{"opts": [["Atoms are mostly empty space \u2014 most particles found no matter to deflect them", true], ["Gold atoms are very large \u2014 the particles passed through the gaps between atoms", false], ["Alpha particles are too fast to be deflected", false], ["The plum pudding model was correct \u2014 the positive charge is spread out", false]], "q": "In Rutherford's gold foil experiment, most alpha particles passed straight through the foil. What does this tell us?", "wrong_explanations": {"1": "Atomic SIZE explains why particles might miss atoms, not why they pass THROUGH them. The key conclusion is that the atom is mostly empty space internally.", "2": "Alpha particles can be deflected \u2014 some WERE deflected at large angles, showing the nucleus exists.", "3": "The plum pudding model predicted only SMALL deflections. The large angle deflections and back-scattering DISPROVED the plum pudding model."}}, {"opts": [["The gold foil experiment produced results that could not be explained by the plum pudding model \u2014 the new model fitted the evidence", true], ["Rutherford was more famous than Thomson, so his model was believed", false], ["The plum pudding model was proposed before electrons were discovered", false], ["Both models are still equally accepted today", false]], "q": "Why did the scientific community accept Rutherford's nuclear model over Thomson's plum pudding model?", "wrong_explanations": {"1": "Scientific acceptance is based on EVIDENCE, not reputation \u2014 the gold foil results clearly contradicted the plum pudding model.", "2": "Thomson's plum pudding model was specifically based on and designed to explain the discovery of electrons.", "3": "Rutherford's nuclear model replaced the plum pudding model \u2014 it is not still equally accepted, though both are discussed historically."}}], "CH": [{"opts": [["Atoms are mostly empty space \u2014 most particles found no matter to deflect them", true], ["Gold atoms are very large \u2014 the particles passed through the gaps between atoms", false], ["Alpha particles are too fast to be deflected", false], ["The plum pudding model was correct \u2014 the positive charge is spread out", false]], "q": "In Rutherford's gold foil experiment, most alpha particles passed straight through the foil. What does this tell us?", "wrong_explanations": {"1": "Atomic SIZE explains why particles might miss atoms, not why they pass THROUGH them. The key conclusion is that the atom is mostly empty space internally.", "2": "Alpha particles can be deflected \u2014 some WERE deflected at large angles, showing the nucleus exists.", "3": "The plum pudding model predicted only SMALL deflections. The large angle deflections and back-scattering DISPROVED the plum pudding model."}}, {"opts": [["The gold foil experiment produced results that could not be explained by the plum pudding model \u2014 the new model fitted the evidence", true], ["Rutherford was more famous than Thomson, so his model was believed", false], ["The plum pudding model was proposed before electrons were discovered", false], ["Both models are still equally accepted today", false]], "q": "Why did the scientific community accept Rutherford's nuclear model over Thomson's plum pudding model?", "wrong_explanations": {"1": "Scientific acceptance is based on EVIDENCE, not reputation \u2014 the gold foil results clearly contradicted the plum pudding model.", "2": "Thomson's plum pudding model was specifically based on and designed to explain the discovery of electrons.", "3": "Rutherford's nuclear model replaced the plum pudding model \u2014 it is not still equally accepted, though both are discussed historically."}}], "TF": [{"opts": [["Atoms are mostly empty space \u2014 most particles found no matter to deflect them", true], ["Gold atoms are very large \u2014 the particles passed through the gaps between atoms", false], ["Alpha particles are too fast to be deflected", false], ["The plum pudding model was correct \u2014 the positive charge is spread out", false]], "q": "In Rutherford's gold foil experiment, most alpha particles passed straight through the foil. What does this tell us?", "wrong_explanations": {"1": "Atomic SIZE explains why particles might miss atoms, not why they pass THROUGH them. The key conclusion is that the atom is mostly empty space internally.", "2": "Alpha particles can be deflected \u2014 some WERE deflected at large angles, showing the nucleus exists.", "3": "The plum pudding model predicted only SMALL deflections. The large angle deflections and back-scattering DISPROVED the plum pudding model."}}, {"opts": [["The gold foil experiment produced results that could not be explained by the plum pudding model \u2014 the new model fitted the evidence", true], ["Rutherford was more famous than Thomson, so his model was believed", false], ["The plum pudding model was proposed before electrons were discovered", false], ["Both models are still equally accepted today", false]], "q": "Why did the scientific community accept Rutherford's nuclear model over Thomson's plum pudding model?", "wrong_explanations": {"1": "Scientific acceptance is based on EVIDENCE, not reputation \u2014 the gold foil results clearly contradicted the plum pudding model.", "2": "Thomson's plum pudding model was specifically based on and designed to explain the discovery of electrons.", "3": "Rutherford's nuclear model replaced the plum pudding model \u2014 it is not still equally accepted, though both are discussed historically."}}], "TH": [{"opts": [["Atoms are mostly empty space \u2014 most particles found no matter to deflect them", true], ["Gold atoms are very large \u2014 the particles passed through the gaps between atoms", false], ["Alpha particles are too fast to be deflected", false], ["The plum pudding model was correct \u2014 the positive charge is spread out", false]], "q": "In Rutherford's gold foil experiment, most alpha particles passed straight through the foil. What does this tell us?", "wrong_explanations": {"1": "Atomic SIZE explains why particles might miss atoms, not why they pass THROUGH them. The key conclusion is that the atom is mostly empty space internally.", "2": "Alpha particles can be deflected \u2014 some WERE deflected at large angles, showing the nucleus exists.", "3": "The plum pudding model predicted only SMALL deflections. The large angle deflections and back-scattering DISPROVED the plum pudding model."}}, {"opts": [["The gold foil experiment produced results that could not be explained by the plum pudding model \u2014 the new model fitted the evidence", true], ["Rutherford was more famous than Thomson, so his model was believed", false], ["The plum pudding model was proposed before electrons were discovered", false], ["Both models are still equally accepted today", false]], "q": "Why did the scientific community accept Rutherford's nuclear model over Thomson's plum pudding model?", "wrong_explanations": {"1": "Scientific acceptance is based on EVIDENCE, not reputation \u2014 the gold foil results clearly contradicted the plum pudding model.", "2": "Thomson's plum pudding model was specifically based on and designed to explain the discovery of electrons.", "3": "Rutherford's nuclear model replaced the plum pudding model \u2014 it is not still equally accepted, though both are discussed historically."}}]}, "summary": "Describe how the model of the atom developed as new evidence was discovered.", "theory": [{"content": "Scientific models are the best current explanation of how something works \u2014 but they must change when new experimental evidence cannot be explained by the existing model.\n\nThe history of atomic models is a perfect example of how science works:\nA model is proposed \u2192 experiments are done \u2192 if results conflict with the model, the model is revised.\n\nThe key models in chronological order:\n1. Dalton's solid sphere (1803)\n2. Thomson's plum pudding model (1897)\n3. Rutherford's nuclear model (1911)\n4. Bohr's shell model (1913)", "heading": "Why Scientific Models Change"}, {"content": "DALTON'S MODEL (1803):\nAtoms are solid, indivisible spheres.\nDifferent elements have differently sized spheres.\nAtoms cannot be split, created or destroyed.\nRevised when electrons were discovered.\n\nTHOMSON'S PLUM PUDDING MODEL (1897):\nDiscovery of the ELECTRON \u2014 a tiny negatively charged particle inside atoms \u2014 proved atoms were not solid or indivisible.\nThomson proposed: an atom is a ball of POSITIVE CHARGE with ELECTRONS dotted throughout \u2014 like plums in a pudding (or currants in a bun).\nRevised after Rutherford's gold foil experiment.\n\nRUTHERFORD'S NUCLEAR MODEL (1911):\nRutherford fired positively charged ALPHA PARTICLES at a very thin sheet of gold foil.\nExpected (plum pudding): all particles would pass through with small deflections.\nObserved:\nMOST particles passed STRAIGHT THROUGH \u2014 atoms are mostly empty space.\nSOME were deflected at large angles \u2014 something positive inside repelled them.\nA FEW bounced STRAIGHT BACK \u2014 hit something very dense and concentrated.\nConclusion: atoms have a tiny, dense, positively charged NUCLEUS at the centre, surrounded by mostly empty space with electrons.\n\nBOHR'S MODEL (1913):\nBohr proposed electrons orbit in fixed SHELLS (energy levels) at specific distances from the nucleus.\nEach shell has a fixed energy \u2014 electrons can jump between shells by absorbing or emitting energy.", "heading": "From Solid Sphere to Nuclear Model"}, {"content": "After Bohr's model, further work led to the modern understanding:\n\nProtons and neutrons were later identified in the nucleus.\nNEUTRON discovery (Chadwick, 1932) explained why atomic mass was not just the number of protons.\n\nWhy each model was better:\nDalton \u2192 Thomson: discovery of the electron showed atoms had internal structure.\nThomson \u2192 Rutherford: gold foil experiment showed positive charge was concentrated in a tiny nucleus, not spread throughout.\nRutherford \u2192 Bohr: observed line spectra of hydrogen showed electrons could only occupy specific energy levels.\n\nThis chain of model improvements shows the power of the scientific method \u2014 each experiment built on previous knowledge and revealed new detail about atomic structure.", "heading": "The Modern Understanding"}]};
window.KS4SRC["subatomic-particles"] = {"common_mistake": "The number of PROTONS never changes in a chemical reaction \u2014 only electrons are gained or lost to form ions. Also: electrons have negligible mass \u2014 almost all atomic mass is in the nucleus (protons + neutrons both have relative mass 1). The atom is MOSTLY EMPTY SPACE \u2014 the nucleus is 10,000 times smaller than the atom.", "key_note": "Proton: +1, mass 1, nucleus. Neutron: 0, mass 1, nucleus. Electron: \u22121, mass ~0, shells. Neutral atom: protons = electrons. Atom loses electrons \u2192 positive ion. Atom gains electrons \u2192 negative ion. Atom mostly empty space \u2014 nucleus is tiny.", "matching": {"instruction": "Match each particle to its charge, mass and location.", "pairs": [["Proton", "Relative charge +1, mass 1 \u2014 in the nucleus"], ["Neutron", "Relative charge 0, mass 1 \u2014 in the nucleus"], ["Electron", "Relative charge \u22121, mass ~0 \u2014 in shells around the nucleus"], ["Na\u207a ion", "Sodium atom that has LOST one electron \u2014 11 protons, 10 electrons"], ["Cl\u207b ion", "Chlorine atom that has GAINED one electron \u2014 17 protons, 18 electrons"]], "title": "Match the Subatomic Particle"}, "quiz": {"CF": [{"opts": [["10 \u2014 magnesium loses 2 electrons from its original 12", true], ["14 \u2014 magnesium gains 2 electrons to form a +2 ion", false], ["12 \u2014 the number of electrons stays the same", false], ["2 \u2014 only the outermost electrons remain", false]], "q": "A magnesium atom (Mg, atomic number 12) forms a Mg\u00b2\u207a ion. How many electrons does the ion have?", "wrong_explanations": {"1": "Gaining electrons gives a NEGATIVE charge. Mg\u00b2\u207a is POSITIVE, so electrons were LOST.", "2": "Mg\u00b2\u207a is formed by losing 2 electrons. Original: 12 electrons. After loss: 12 \u2212 2 = 10 electrons.", "3": "Only the 2 outermost electrons are lost \u2014 but the ion still has all 10 remaining electrons, not just 2."}}, {"opts": [["The number of protons (+1 each) equals the number of electrons (\u22121 each) \u2014 the charges cancel", true], ["Protons and neutrons have equal and opposite charges that cancel", false], ["Electrons are on the outside and shield the positive nucleus", false], ["The atom vibrates too fast for any charge to accumulate", false]], "q": "Why does an atom have no overall electrical charge?", "wrong_explanations": {"1": "Neutrons have ZERO charge \u2014 they cannot cancel proton charges. Charge neutrality comes from protons balancing electrons.", "2": "Shielding describes how inner electrons reduce the attractive force on outer electrons \u2014 it does not explain why atoms are electrically neutral.", "3": "Vibration does not affect electrical charge \u2014 the neutrality is a consequence of proton and electron numbers being equal."}}], "CH": [{"opts": [["10 \u2014 magnesium loses 2 electrons from its original 12", true], ["14 \u2014 magnesium gains 2 electrons to form a +2 ion", false], ["12 \u2014 the number of electrons stays the same", false], ["2 \u2014 only the outermost electrons remain", false]], "q": "A magnesium atom (Mg, atomic number 12) forms a Mg\u00b2\u207a ion. How many electrons does the ion have?", "wrong_explanations": {"1": "Gaining electrons gives a NEGATIVE charge. Mg\u00b2\u207a is POSITIVE, so electrons were LOST.", "2": "Mg\u00b2\u207a is formed by losing 2 electrons. Original: 12 electrons. After loss: 12 \u2212 2 = 10 electrons.", "3": "Only the 2 outermost electrons are lost \u2014 but the ion still has all 10 remaining electrons, not just 2."}}, {"opts": [["The number of protons (+1 each) equals the number of electrons (\u22121 each) \u2014 the charges cancel", true], ["Protons and neutrons have equal and opposite charges that cancel", false], ["Electrons are on the outside and shield the positive nucleus", false], ["The atom vibrates too fast for any charge to accumulate", false]], "q": "Why does an atom have no overall electrical charge?", "wrong_explanations": {"1": "Neutrons have ZERO charge \u2014 they cannot cancel proton charges. Charge neutrality comes from protons balancing electrons.", "2": "Shielding describes how inner electrons reduce the attractive force on outer electrons \u2014 it does not explain why atoms are electrically neutral.", "3": "Vibration does not affect electrical charge \u2014 the neutrality is a consequence of proton and electron numbers being equal."}}], "TF": [{"opts": [["10 \u2014 magnesium loses 2 electrons from its original 12", true], ["14 \u2014 magnesium gains 2 electrons to form a +2 ion", false], ["12 \u2014 the number of electrons stays the same", false], ["2 \u2014 only the outermost electrons remain", false]], "q": "A magnesium atom (Mg, atomic number 12) forms a Mg\u00b2\u207a ion. How many electrons does the ion have?", "wrong_explanations": {"1": "Gaining electrons gives a NEGATIVE charge. Mg\u00b2\u207a is POSITIVE, so electrons were LOST.", "2": "Mg\u00b2\u207a is formed by losing 2 electrons. Original: 12 electrons. After loss: 12 \u2212 2 = 10 electrons.", "3": "Only the 2 outermost electrons are lost \u2014 but the ion still has all 10 remaining electrons, not just 2."}}, {"opts": [["The number of protons (+1 each) equals the number of electrons (\u22121 each) \u2014 the charges cancel", true], ["Protons and neutrons have equal and opposite charges that cancel", false], ["Electrons are on the outside and shield the positive nucleus", false], ["The atom vibrates too fast for any charge to accumulate", false]], "q": "Why does an atom have no overall electrical charge?", "wrong_explanations": {"1": "Neutrons have ZERO charge \u2014 they cannot cancel proton charges. Charge neutrality comes from protons balancing electrons.", "2": "Shielding describes how inner electrons reduce the attractive force on outer electrons \u2014 it does not explain why atoms are electrically neutral.", "3": "Vibration does not affect electrical charge \u2014 the neutrality is a consequence of proton and electron numbers being equal."}}], "TH": [{"opts": [["10 \u2014 magnesium loses 2 electrons from its original 12", true], ["14 \u2014 magnesium gains 2 electrons to form a +2 ion", false], ["12 \u2014 the number of electrons stays the same", false], ["2 \u2014 only the outermost electrons remain", false]], "q": "A magnesium atom (Mg, atomic number 12) forms a Mg\u00b2\u207a ion. How many electrons does the ion have?", "wrong_explanations": {"1": "Gaining electrons gives a NEGATIVE charge. Mg\u00b2\u207a is POSITIVE, so electrons were LOST.", "2": "Mg\u00b2\u207a is formed by losing 2 electrons. Original: 12 electrons. After loss: 12 \u2212 2 = 10 electrons.", "3": "Only the 2 outermost electrons are lost \u2014 but the ion still has all 10 remaining electrons, not just 2."}}, {"opts": [["The number of protons (+1 each) equals the number of electrons (\u22121 each) \u2014 the charges cancel", true], ["Protons and neutrons have equal and opposite charges that cancel", false], ["Electrons are on the outside and shield the positive nucleus", false], ["The atom vibrates too fast for any charge to accumulate", false]], "q": "Why does an atom have no overall electrical charge?", "wrong_explanations": {"1": "Neutrons have ZERO charge \u2014 they cannot cancel proton charges. Charge neutrality comes from protons balancing electrons.", "2": "Shielding describes how inner electrons reduce the attractive force on outer electrons \u2014 it does not explain why atoms are electrically neutral.", "3": "Vibration does not affect electrical charge \u2014 the neutrality is a consequence of proton and electron numbers being equal."}}]}, "summary": "Describe the relative charges and masses of protons, neutrons and electrons and the scale of atoms.", "theory": [{"content": "Every atom contains three types of subatomic particle:\n\nPROTON:\nFound in the NUCLEUS.\nRelative charge: +1.\nRelative mass: 1.\n\nNEUTRON:\nFound in the NUCLEUS.\nRelative charge: 0 (neutral).\nRelative mass: 1.\n\nELECTRON:\nFound in SHELLS (energy levels) around the nucleus.\nRelative charge: \u22121.\nRelative mass: approximately 1/1836 \u2014 effectively 0 in relative terms.\n\nAtoms are electrically NEUTRAL because the number of protons = number of electrons (positive and negative charges cancel).\n\nThe NUCLEUS contains protons and neutrons \u2014 almost all of the atom's mass is concentrated here.\nElectrons contribute negligible mass.", "heading": "The Three Subatomic Particles"}, {"content": "An ION is a charged particle formed when an atom gains or loses electrons.\n\nATOM LOSES ELECTRONS \u2192 positive ion (cation)\nExample: Na \u2192 Na\u207a + e\u207b (sodium loses 1 electron \u2192 +1 charge)\nExample: Mg \u2192 Mg\u00b2\u207a + 2e\u207b (magnesium loses 2 electrons \u2192 +2 charge)\n\nATOM GAINS ELECTRONS \u2192 negative ion (anion)\nExample: Cl + e\u207b \u2192 Cl\u207b (chlorine gains 1 electron \u2192 \u22121 charge)\nExample: O + 2e\u207b \u2192 O\u00b2\u207b (oxygen gains 2 electrons \u2192 \u22122 charge)\n\nThe charge on an ion tells you how many electrons were gained or lost.\nThe NUMBER OF PROTONS never changes in a chemical reaction \u2014 only electron numbers change.", "heading": "Ions \u2014 When Atoms Gain or Lose Electrons"}, {"content": "Atoms are incredibly small \u2014 they cannot be seen with a light microscope.\n\nA typical atomic radius \u2248 1 \u00d7 10\u207b\u00b9\u2070 m (0.1 nanometres).\nA human hair is about 1 million atoms wide.\nA grain of sand contains approximately 10\u00b9\u2078 atoms.\n\nThe NUCLEUS is even smaller \u2014 about 10,000 times smaller than the whole atom:\nNuclear radius \u2248 1 \u00d7 10\u207b\u00b9\u2074 m\n\nThis means the atom is almost entirely EMPTY SPACE \u2014 the nucleus is tiny compared to the overall size of the atom, with electrons in the vast space around it.\n\nThis is consistent with what Rutherford found \u2014 most alpha particles passing straight through gold foil without hitting anything.", "heading": "Size and Scale of Atoms"}]};
window.KS4SRC["relative-atomic-mass"] = {"common_mistake": "Ar is a WEIGHTED average \u2014 not a simple average. Chlorine has Ar 35.5 because ~75% is Cl-35 and only ~25% is Cl-37. If both were 50/50, Ar would be 36. The heavier isotope has LESS influence because it's less abundant. Also: isotopes have SAME chemical properties (same electrons) but DIFFERENT physical properties (different mass).", "equations": ["Mass number = protons + neutrons", "Neutrons = mass number \u2212 atomic number", "Ar = \u03a3(% abundance \u00d7 mass number) \u00f7 100"], "fifas": [{"label": "Relative Atomic Mass Calculation", "question": "Boron has two isotopes: 20% boron-10 and 80% boron-11. Calculate the relative atomic mass of boron.", "steps": [["F", "Ar = \u03a3(% abundance \u00d7 mass number) \u00f7 100"], ["I", "Ar = (20 \u00d7 10) + (80 \u00d7 11) \u00f7 100"], ["F", "Ar = (200 + 880) \u00f7 100 = 1080 \u00f7 100"], ["A", "Ar = 10.8"]]}], "higher": "Use mass spectrometry data to calculate Ar from isotope masses and percentage abundances. Interpret mass spectra showing relative abundance on y-axis and mass/charge on x-axis. Understand that non-integer Ar values result from isotope mixtures.", "key_note": "Atomic number = protons. Mass number = protons + neutrons. Neutrons = mass number \u2212 atomic number. Isotopes: same element, same protons, different neutrons \u2014 same chemical, different physical properties. Ar = weighted average of isotope masses.", "matching": {"instruction": "Match each term to its correct definition.", "pairs": [["Atomic number", "Number of protons \u2014 unique to each element"], ["Mass number", "Total protons + neutrons in the nucleus"], ["Isotopes", "Same element, same protons, different number of neutrons"], ["Relative atomic mass", "Weighted average of all isotope masses \u2014 often not a whole number"], ["Number of neutrons", "Mass number minus atomic number"]], "title": "Atomic Number, Mass Number and Isotopes"}, "quiz": {"CF": [{"opts": [["Same: atomic number (17 protons and 17 electrons). Different: mass number \u2014 Cl-35 has 18 neutrons, Cl-37 has 20 neutrons.", true], ["Same: mass number. Different: atomic number and proton count.", false], ["Same: everything \u2014 isotopes are identical atoms.", false], ["Same: neutron number. Different: proton number.", false]], "q": "Chlorine-35 and chlorine-37 are isotopes. What is the same and what differs between them?", "wrong_explanations": {"1": "If mass numbers were the same they would be identical \u2014 isotopes are DEFINED by having different mass numbers.", "2": "Isotopes DO have the same chemical properties \u2014 but they are NOT identical. They differ in neutron count and mass.", "3": "If neutron numbers were the same but proton numbers differed, they would be different ELEMENTS \u2014 not isotopes."}}, {"opts": [["63.8 \u2014 Ar = (60 \u00d7 63 + 40 \u00d7 65) \u00f7 100 = 6380 \u00f7 100", true], ["64.0 \u2014 simple average of 63 and 65", false], ["128 \u2014 total of both mass numbers added together", false], ["63 \u2014 just the most abundant isotope mass", false]], "q": "An element has two isotopes: 60% at mass 63 and 40% at mass 65. What is its Ar?", "wrong_explanations": {"1": "Simple average gives 64 only if BOTH isotopes are 50/50 abundant. Since there is more of the lighter isotope (60% at mass 63), the weighted average is pulled below 64.", "2": "Adding mass numbers has no physical meaning \u2014 Ar is a weighted average, not a sum.", "3": "Using only the most abundant isotope ignores the 40% contribution from mass 65 \u2014 the true Ar is pulled above 63 by the heavier isotope."}}], "CH": [{"opts": [["Same: atomic number (17 protons and 17 electrons). Different: mass number \u2014 Cl-35 has 18 neutrons, Cl-37 has 20 neutrons.", true], ["Same: mass number. Different: atomic number and proton count.", false], ["Same: everything \u2014 isotopes are identical atoms.", false], ["Same: neutron number. Different: proton number.", false]], "q": "Chlorine-35 and chlorine-37 are isotopes. What is the same and what differs between them?", "wrong_explanations": {"1": "If mass numbers were the same they would be identical \u2014 isotopes are DEFINED by having different mass numbers.", "2": "Isotopes DO have the same chemical properties \u2014 but they are NOT identical. They differ in neutron count and mass.", "3": "If neutron numbers were the same but proton numbers differed, they would be different ELEMENTS \u2014 not isotopes."}}, {"opts": [["63.8 \u2014 Ar = (60 \u00d7 63 + 40 \u00d7 65) \u00f7 100 = 6380 \u00f7 100", true], ["64.0 \u2014 simple average of 63 and 65", false], ["128 \u2014 total of both mass numbers added together", false], ["63 \u2014 just the most abundant isotope mass", false]], "q": "An element has two isotopes: 60% at mass 63 and 40% at mass 65. What is its Ar?", "wrong_explanations": {"1": "Simple average gives 64 only if BOTH isotopes are 50/50 abundant. Since there is more of the lighter isotope (60% at mass 63), the weighted average is pulled below 64.", "2": "Adding mass numbers has no physical meaning \u2014 Ar is a weighted average, not a sum.", "3": "Using only the most abundant isotope ignores the 40% contribution from mass 65 \u2014 the true Ar is pulled above 63 by the heavier isotope."}}], "TF": [{"opts": [["Same: atomic number (17 protons and 17 electrons). Different: mass number \u2014 Cl-35 has 18 neutrons, Cl-37 has 20 neutrons.", true], ["Same: mass number. Different: atomic number and proton count.", false], ["Same: everything \u2014 isotopes are identical atoms.", false], ["Same: neutron number. Different: proton number.", false]], "q": "Chlorine-35 and chlorine-37 are isotopes. What is the same and what differs between them?", "wrong_explanations": {"1": "If mass numbers were the same they would be identical \u2014 isotopes are DEFINED by having different mass numbers.", "2": "Isotopes DO have the same chemical properties \u2014 but they are NOT identical. They differ in neutron count and mass.", "3": "If neutron numbers were the same but proton numbers differed, they would be different ELEMENTS \u2014 not isotopes."}}, {"opts": [["63.8 \u2014 Ar = (60 \u00d7 63 + 40 \u00d7 65) \u00f7 100 = 6380 \u00f7 100", true], ["64.0 \u2014 simple average of 63 and 65", false], ["128 \u2014 total of both mass numbers added together", false], ["63 \u2014 just the most abundant isotope mass", false]], "q": "An element has two isotopes: 60% at mass 63 and 40% at mass 65. What is its Ar?", "wrong_explanations": {"1": "Simple average gives 64 only if BOTH isotopes are 50/50 abundant. Since there is more of the lighter isotope (60% at mass 63), the weighted average is pulled below 64.", "2": "Adding mass numbers has no physical meaning \u2014 Ar is a weighted average, not a sum.", "3": "Using only the most abundant isotope ignores the 40% contribution from mass 65 \u2014 the true Ar is pulled above 63 by the heavier isotope."}}], "TH": [{"opts": [["Same: atomic number (17 protons and 17 electrons). Different: mass number \u2014 Cl-35 has 18 neutrons, Cl-37 has 20 neutrons.", true], ["Same: mass number. Different: atomic number and proton count.", false], ["Same: everything \u2014 isotopes are identical atoms.", false], ["Same: neutron number. Different: proton number.", false]], "q": "Chlorine-35 and chlorine-37 are isotopes. What is the same and what differs between them?", "wrong_explanations": {"1": "If mass numbers were the same they would be identical \u2014 isotopes are DEFINED by having different mass numbers.", "2": "Isotopes DO have the same chemical properties \u2014 but they are NOT identical. They differ in neutron count and mass.", "3": "If neutron numbers were the same but proton numbers differed, they would be different ELEMENTS \u2014 not isotopes."}}, {"opts": [["63.8 \u2014 Ar = (60 \u00d7 63 + 40 \u00d7 65) \u00f7 100 = 6380 \u00f7 100", true], ["64.0 \u2014 simple average of 63 and 65", false], ["128 \u2014 total of both mass numbers added together", false], ["63 \u2014 just the most abundant isotope mass", false]], "q": "An element has two isotopes: 60% at mass 63 and 40% at mass 65. What is its Ar?", "wrong_explanations": {"1": "Simple average gives 64 only if BOTH isotopes are 50/50 abundant. Since there is more of the lighter isotope (60% at mass 63), the weighted average is pulled below 64.", "2": "Adding mass numbers has no physical meaning \u2014 Ar is a weighted average, not a sum.", "3": "Using only the most abundant isotope ignores the 40% contribution from mass 65 \u2014 the true Ar is pulled above 63 by the heavier isotope."}}]}, "summary": "Define atomic number, mass number, isotopes and relative atomic mass \u2014 and calculate Ar from isotope abundances.", "theory": [{"content": "Every element is defined by its ATOMIC NUMBER (proton number):\n\nATOMIC NUMBER (Z) = number of PROTONS in the nucleus.\nThis is unique to each element \u2014 all carbon atoms have 6 protons, all iron atoms have 26.\nIn a neutral atom: protons = electrons.\n\nMASS NUMBER (A) = total number of PROTONS + NEUTRONS in the nucleus.\n\nFrom these two numbers:\nNeutrons = mass number \u2212 atomic number\n\nExample \u2014 sodium-23:\nMass number = 23, atomic number = 11.\nProtons = 11, electrons = 11 (neutral), neutrons = 23 \u2212 11 = 12.\n\nIn the periodic table, the ATOMIC NUMBER is the SMALLER number (it cannot exceed the mass number as you cannot have negative neutrons).", "heading": "Atomic Number and Mass Number"}, {"content": "ISOTOPES are atoms of the SAME ELEMENT with the SAME ATOMIC NUMBER but DIFFERENT MASS NUMBERS.\n\nSame protons \u2192 same element \u2192 same chemical properties.\nDifferent neutrons \u2192 different mass \u2192 different physical properties (e.g. density, rate of diffusion).\n\nIsotopes have IDENTICAL CHEMICAL behaviour \u2014 because chemical reactions depend on electron configuration (determined by proton number, which is the same).\n\nExamples:\nCARBON ISOTOPES:\nCarbon-12 (\u00b9\u00b2C): 6p + 6n \u2014 the standard (98.9% of carbon)\nCarbon-13 (\u00b9\u00b3C): 6p + 7n \u2014 stable, ~1.1%\nCarbon-14 (\u00b9\u2074C): 6p + 8n \u2014 radioactive, used in carbon dating\n\nCHLORINE ISOTOPES:\nChlorine-35 (\u00b3\u2075Cl): 17p + 18n \u2014 ~75% of chlorine\nChlorine-37 (\u00b3\u2077Cl): 17p + 20n \u2014 ~25% of chlorine\nBecause of this mixture, the Ar of chlorine \u2248 35.5 \u2014 between the two isotope masses.", "heading": "Isotopes"}, {"content": "The RELATIVE ATOMIC MASS (Ar) is the WEIGHTED AVERAGE mass of all atoms of an element compared to 1/12 of the mass of a carbon-12 atom.\n\nBecause most elements have multiple isotopes in different abundances, Ar is NOT a whole number.\n\nFormula:\nAr = \u03a3 (% abundance \u00d7 mass number) \u00f7 100\n\nExample \u2014 chlorine:\nAr = (75 \u00d7 35 + 25 \u00d7 37) \u00f7 100\nAr = (2625 + 925) \u00f7 100\nAr = 3550 \u00f7 100 = 35.5\n\nThis explains why periodic table Ar values are often not whole numbers \u2014 they are weighted averages across all naturally occurring isotopes.", "heading": "Relative Atomic Mass"}]};
window.KS4SRC["electronic-structure"] = {"common_mistake": "Always fill shells in ORDER \u2014 2 in the first, then 8 in the second, then continue. The 3rd shell fills to 8 before the 4th shell starts. Students sometimes try to put more than 8 in the 3rd shell for early elements \u2014 for the first 20, the 3rd shell only goes up to 8.", "higher": "Electronic configurations for all elements 1\u201320. Predict chemical properties from electronic structure \u2014 elements in the same group have the same outer electron count. Explain why period number = number of shells, and group number = outer electrons.", "key_note": "Shells fill innermost first: 2, 8, 8. Electronic configuration written as numbers separated by dots (e.g. 2.8.3 for Al). Same group = same outer electrons = similar chemistry. Full outer shell = stable (noble gas configuration).", "matching": {"instruction": "Match each element to its correct electronic configuration.", "pairs": [["Sodium (Na, 11)", "2.8.1 \u2014 11 electrons: 2 in shell 1, 8 in shell 2, 1 in shell 3"], ["Chlorine (Cl, 17)", "2.8.7 \u2014 17 electrons: 2 in shell 1, 8 in shell 2, 7 in shell 3"], ["Calcium (Ca, 20)", "2.8.8.2 \u2014 20 electrons across four shells"], ["Neon (Ne, 10)", "2.8 \u2014 full outer shell, noble gas, very unreactive"], ["Magnesium (Mg, 12)", "2.8.2 \u2014 2 outer electrons, Group 2 element"]], "title": "Match the Element to its Electronic Configuration"}, "quiz": {"CF": [{"opts": [["Group 6 \u2014 it has 6 electrons in its outermost shell", true], ["Group 2 \u2014 there are 2 complete shells below the outer shell", false], ["Group 16 \u2014 add all the electrons together", false], ["Period 3 \u2014 it has 3 shells", false]], "q": "An element has the electronic configuration 2.8.6. Which group of the periodic table is it in?", "wrong_explanations": {"1": "The number of complete inner shells tells you the PERIOD \u2014 2 inner shells means Period 3. Groups are determined by OUTER electrons.", "2": "16 is the total number of electrons (2+8+6) \u2014 this tells you the atomic number, not the group.", "3": "The NUMBER OF SHELLS tells you the PERIOD (3 shells = Period 3). The GROUP is determined by the number of OUTER electrons (6)."}}, {"opts": [["Both have 1 electron in their outer shell \u2014 they react in similar ways to achieve a full outer shell", true], ["Both have the same total number of electrons", false], ["Both are in the same period of the periodic table", false], ["Both have the same mass number", false]], "q": "Why do lithium (2.1) and sodium (2.8.1) have similar chemical properties?", "wrong_explanations": {"1": "Li has 3 electrons total, Na has 11 \u2014 very different totals, but the same outer shell count (1) is what matters for reactivity.", "2": "Li is Period 2, Na is Period 3 \u2014 they are in different periods. Same GROUP, different periods.", "3": "Li has mass number 7, Na has mass number 23 \u2014 different mass numbers. Chemical similarity comes from electron configuration."}}], "CH": [{"opts": [["Group 6 \u2014 it has 6 electrons in its outermost shell", true], ["Group 2 \u2014 there are 2 complete shells below the outer shell", false], ["Group 16 \u2014 add all the electrons together", false], ["Period 3 \u2014 it has 3 shells", false]], "q": "An element has the electronic configuration 2.8.6. Which group of the periodic table is it in?", "wrong_explanations": {"1": "The number of complete inner shells tells you the PERIOD \u2014 2 inner shells means Period 3. Groups are determined by OUTER electrons.", "2": "16 is the total number of electrons (2+8+6) \u2014 this tells you the atomic number, not the group.", "3": "The NUMBER OF SHELLS tells you the PERIOD (3 shells = Period 3). The GROUP is determined by the number of OUTER electrons (6)."}}, {"opts": [["Both have 1 electron in their outer shell \u2014 they react in similar ways to achieve a full outer shell", true], ["Both have the same total number of electrons", false], ["Both are in the same period of the periodic table", false], ["Both have the same mass number", false]], "q": "Why do lithium (2.1) and sodium (2.8.1) have similar chemical properties?", "wrong_explanations": {"1": "Li has 3 electrons total, Na has 11 \u2014 very different totals, but the same outer shell count (1) is what matters for reactivity.", "2": "Li is Period 2, Na is Period 3 \u2014 they are in different periods. Same GROUP, different periods.", "3": "Li has mass number 7, Na has mass number 23 \u2014 different mass numbers. Chemical similarity comes from electron configuration."}}], "TF": [{"opts": [["Group 6 \u2014 it has 6 electrons in its outermost shell", true], ["Group 2 \u2014 there are 2 complete shells below the outer shell", false], ["Group 16 \u2014 add all the electrons together", false], ["Period 3 \u2014 it has 3 shells", false]], "q": "An element has the electronic configuration 2.8.6. Which group of the periodic table is it in?", "wrong_explanations": {"1": "The number of complete inner shells tells you the PERIOD \u2014 2 inner shells means Period 3. Groups are determined by OUTER electrons.", "2": "16 is the total number of electrons (2+8+6) \u2014 this tells you the atomic number, not the group.", "3": "The NUMBER OF SHELLS tells you the PERIOD (3 shells = Period 3). The GROUP is determined by the number of OUTER electrons (6)."}}, {"opts": [["Both have 1 electron in their outer shell \u2014 they react in similar ways to achieve a full outer shell", true], ["Both have the same total number of electrons", false], ["Both are in the same period of the periodic table", false], ["Both have the same mass number", false]], "q": "Why do lithium (2.1) and sodium (2.8.1) have similar chemical properties?", "wrong_explanations": {"1": "Li has 3 electrons total, Na has 11 \u2014 very different totals, but the same outer shell count (1) is what matters for reactivity.", "2": "Li is Period 2, Na is Period 3 \u2014 they are in different periods. Same GROUP, different periods.", "3": "Li has mass number 7, Na has mass number 23 \u2014 different mass numbers. Chemical similarity comes from electron configuration."}}], "TH": [{"opts": [["Group 6 \u2014 it has 6 electrons in its outermost shell", true], ["Group 2 \u2014 there are 2 complete shells below the outer shell", false], ["Group 16 \u2014 add all the electrons together", false], ["Period 3 \u2014 it has 3 shells", false]], "q": "An element has the electronic configuration 2.8.6. Which group of the periodic table is it in?", "wrong_explanations": {"1": "The number of complete inner shells tells you the PERIOD \u2014 2 inner shells means Period 3. Groups are determined by OUTER electrons.", "2": "16 is the total number of electrons (2+8+6) \u2014 this tells you the atomic number, not the group.", "3": "The NUMBER OF SHELLS tells you the PERIOD (3 shells = Period 3). The GROUP is determined by the number of OUTER electrons (6)."}}, {"opts": [["Both have 1 electron in their outer shell \u2014 they react in similar ways to achieve a full outer shell", true], ["Both have the same total number of electrons", false], ["Both are in the same period of the periodic table", false], ["Both have the same mass number", false]], "q": "Why do lithium (2.1) and sodium (2.8.1) have similar chemical properties?", "wrong_explanations": {"1": "Li has 3 electrons total, Na has 11 \u2014 very different totals, but the same outer shell count (1) is what matters for reactivity.", "2": "Li is Period 2, Na is Period 3 \u2014 they are in different periods. Same GROUP, different periods.", "3": "Li has mass number 7, Na has mass number 23 \u2014 different mass numbers. Chemical similarity comes from electron configuration."}}]}, "summary": "Describe how electrons fill shells and write electronic configurations for the first 20 elements.", "theory": [{"content": "Electrons occupy SHELLS (energy levels) around the nucleus. They always fill from the INNERMOST (lowest energy) shell outward.\n\nSHELL CAPACITIES (for first 20 elements):\n1st shell: maximum 2 electrons.\n2nd shell: maximum 8 electrons.\n3rd shell: maximum 8 electrons.\n\nElectrons are only added to the next shell when the current one is FULL.\n\nExample \u2014 Sodium (Na, atomic number 11):\n11 electrons to distribute.\n1st shell: 2 (full) \u2192 2nd shell: 8 (full) \u2192 3rd shell: 1 remaining.\nElectronic configuration written as: 2.8.1", "heading": "Electron Shells"}, {"content": "H  (1):  1\nHe (2):  2\nLi (3):  2.1\nBe (4):  2.2\nB  (5):  2.3\nC  (6):  2.4\nN  (7):  2.5\nO  (8):  2.6\nF  (9):  2.7\nNe (10): 2.8\nNa (11): 2.8.1\nMg (12): 2.8.2\nAl (13): 2.8.3\nSi (14): 2.8.4\nP  (15): 2.8.5\nS  (16): 2.8.6\nCl (17): 2.8.7\nAr (18): 2.8.8\nK  (19): 2.8.8.1\nCa (20): 2.8.8.2\n\nNote: the 4th shell starts filling at potassium (K) and calcium (Ca) because the 3rd shell fills to 8 before the 4th begins (for these lighter elements).", "heading": "Electronic Configurations of the First 20 Elements"}, {"content": "The NUMBER OF ELECTRONS IN THE OUTERMOST SHELL (valence electrons) determines an element's chemical properties.\n\nElements in the SAME GROUP of the periodic table have the SAME NUMBER of outer electrons:\nGroup 1: 1 outer electron (Li: 2.1, Na: 2.8.1, K: 2.8.8.1)\nGroup 7: 7 outer electrons (F: 2.7, Cl: 2.8.7)\nGroup 0: 8 outer electrons (full shell) \u2014 He: 2, Ne: 2.8, Ar: 2.8.8\n\nThis is why elements in the same group have similar chemical properties \u2014 they react in similar ways to achieve a full outer shell.\n\nATOMS REACT TO ACHIEVE A FULL OUTER SHELL:\nMETALS lose electrons \u2192 form positive ions (cations).\nNON-METALS gain electrons (or share) \u2192 form negative ions (anions) or covalent bonds.\nNOBLE GASES already have full outer shells \u2192 very unreactive.", "heading": "Electronic Structure and Chemical Properties"}]};
window.KS4SRC["group-7"] = {"common_mistake": "Reactivity DECREASES down Group 7 \u2014 the OPPOSITE of Group 1. In Group 1, going down makes metals MORE reactive (outer electron easier to LOSE). In Group 7, going down makes non-metals LESS reactive (harder to GAIN an extra electron when the outer shell is further away).", "equations": ["Cl\u2082 + 2NaBr \u2192 2NaCl + Br\u2082", "Cl\u2082 + 2KI \u2192 2KCl + I\u2082", "Br\u2082 + 2KI \u2192 2KBr + I\u2082"], "higher": "Quantitative explanation: increasing atomic radius down group \u2192 outer shell further from nucleus \u2192 weaker attraction for incoming electron \u2192 lower electron affinity \u2192 less reactive. Astatine predicted to be solid, dark coloured and least reactive halogen. Displacement reactions as reactivity evidence.", "key_note": "Group 7: halogens, 7 outer electrons, form \u22121 ions, diatomic molecules (X\u2082). Boiling point increases down group. Reactivity DECREASES down group (outer shell further away, weaker pull on incoming electron). More reactive halogen displaces less reactive from solution.", "matching": {"instruction": "Predict whether a reaction occurs and match to the correct outcome.", "pairs": [["Reaction occurs", "Cl\u2082 + NaBr solution \u2014 chlorine displaces bromine (Cl more reactive than Br)"], ["Reaction occurs", "Br\u2082 + KI solution \u2014 bromine displaces iodine (Br more reactive than I)"], ["No reaction", "Br\u2082 + NaCl solution \u2014 bromine cannot displace chlorine (Cl is MORE reactive)"], ["Reaction occurs", "Cl\u2082 + KI solution \u2014 chlorine displaces iodine (Cl more reactive than I)"], ["No reaction", "I\u2082 + NaCl solution \u2014 iodine cannot displace chlorine (Cl is much more reactive)"]], "title": "Match the Halogen Displacement Reaction"}, "quiz": {"CF": [{"opts": [["The solution turns orange/brown \u2014 chlorine displaces bromide ions, releasing bromine", true], ["No change \u2014 chlorine cannot react with bromide ions", false], ["The solution turns pale green \u2014 chlorine is absorbed by the solution", false], ["A white precipitate forms \u2014 chlorine reacts with potassium ions", false]], "q": "Chlorine water is added to a solution of potassium bromide. What is observed?", "wrong_explanations": {"1": "Chlorine IS more reactive than bromine and CAN displace bromide \u2014 so a reaction does occur.", "2": "Chlorine water has a yellow-green colour but when it reacts with bromide, the BROWN colour of bromine is what appears in the solution.", "3": "Chlorine does not react with potassium ions \u2014 it displaces bromide ions. No precipitate forms."}}, {"opts": [["Fluorine is a smaller atom \u2014 its outer shell is closer to the nucleus, so it attracts an incoming electron more strongly", true], ["Fluorine has fewer electrons, making it less stable and more reactive", false], ["Fluorine has more protons, making its positive charge stronger", false], ["Fluorine is a gas, making it react more easily than other states of matter", false]], "q": "Why is fluorine more reactive than chlorine?", "wrong_explanations": {"1": "Fewer electrons in an outer shell means the atom needs to GAIN electrons \u2014 but that doesn't directly explain why fluorine attracts electrons more strongly. The distance from the nucleus is the key factor.", "2": "Fluorine does have fewer protons (9) than chlorine (17) \u2014 but its outer shell is MUCH closer to those protons. The closeness wins over the fewer-proton effect.", "3": "Chlorine is also a gas \u2014 being a gas is not the reason fluorine is more reactive."}}, {"opts": [["No reaction \u2014 iodine is less reactive than chlorine and cannot displace it", true], ["Chlorine gas is released \u2014 iodine displaces chloride ions", false], ["A brown precipitate forms \u2014 iodine reacts with sodium ions", false], ["The solution turns pale yellow \u2014 iodine bleaches the solution", false]], "q": "Iodine solution is added to sodium chloride solution. What happens?", "wrong_explanations": {"1": "A more reactive halogen displaces a less reactive one. Iodine is LESS reactive than chlorine \u2014 so iodine cannot displace chloride ions.", "2": "Iodine does not react with sodium ions \u2014 and even if it tried to displace chloride, it couldn't because iodine is less reactive than chlorine.", "3": "Iodine actually turns starch blue-black \u2014 it doesn't bleach. Chlorine is the halogen with bleaching properties."}}], "CH": [{"opts": [["The solution turns orange/brown \u2014 chlorine displaces bromide ions, releasing bromine", true], ["No change \u2014 chlorine cannot react with bromide ions", false], ["The solution turns pale green \u2014 chlorine is absorbed by the solution", false], ["A white precipitate forms \u2014 chlorine reacts with potassium ions", false]], "q": "Chlorine water is added to a solution of potassium bromide. What is observed?", "wrong_explanations": {"1": "Chlorine IS more reactive than bromine and CAN displace bromide \u2014 so a reaction does occur.", "2": "Chlorine water has a yellow-green colour but when it reacts with bromide, the BROWN colour of bromine is what appears in the solution.", "3": "Chlorine does not react with potassium ions \u2014 it displaces bromide ions. No precipitate forms."}}, {"opts": [["Fluorine is a smaller atom \u2014 its outer shell is closer to the nucleus, so it attracts an incoming electron more strongly", true], ["Fluorine has fewer electrons, making it less stable and more reactive", false], ["Fluorine has more protons, making its positive charge stronger", false], ["Fluorine is a gas, making it react more easily than other states of matter", false]], "q": "Why is fluorine more reactive than chlorine?", "wrong_explanations": {"1": "Fewer electrons in an outer shell means the atom needs to GAIN electrons \u2014 but that doesn't directly explain why fluorine attracts electrons more strongly. The distance from the nucleus is the key factor.", "2": "Fluorine does have fewer protons (9) than chlorine (17) \u2014 but its outer shell is MUCH closer to those protons. The closeness wins over the fewer-proton effect.", "3": "Chlorine is also a gas \u2014 being a gas is not the reason fluorine is more reactive."}}, {"opts": [["No reaction \u2014 iodine is less reactive than chlorine and cannot displace it", true], ["Chlorine gas is released \u2014 iodine displaces chloride ions", false], ["A brown precipitate forms \u2014 iodine reacts with sodium ions", false], ["The solution turns pale yellow \u2014 iodine bleaches the solution", false]], "q": "Iodine solution is added to sodium chloride solution. What happens?", "wrong_explanations": {"1": "A more reactive halogen displaces a less reactive one. Iodine is LESS reactive than chlorine \u2014 so iodine cannot displace chloride ions.", "2": "Iodine does not react with sodium ions \u2014 and even if it tried to displace chloride, it couldn't because iodine is less reactive than chlorine.", "3": "Iodine actually turns starch blue-black \u2014 it doesn't bleach. Chlorine is the halogen with bleaching properties."}}], "TF": [{"opts": [["The solution turns orange/brown \u2014 chlorine displaces bromide ions, releasing bromine", true], ["No change \u2014 chlorine cannot react with bromide ions", false], ["The solution turns pale green \u2014 chlorine is absorbed by the solution", false], ["A white precipitate forms \u2014 chlorine reacts with potassium ions", false]], "q": "Chlorine water is added to a solution of potassium bromide. What is observed?", "wrong_explanations": {"1": "Chlorine IS more reactive than bromine and CAN displace bromide \u2014 so a reaction does occur.", "2": "Chlorine water has a yellow-green colour but when it reacts with bromide, the BROWN colour of bromine is what appears in the solution.", "3": "Chlorine does not react with potassium ions \u2014 it displaces bromide ions. No precipitate forms."}}, {"opts": [["Fluorine is a smaller atom \u2014 its outer shell is closer to the nucleus, so it attracts an incoming electron more strongly", true], ["Fluorine has fewer electrons, making it less stable and more reactive", false], ["Fluorine has more protons, making its positive charge stronger", false], ["Fluorine is a gas, making it react more easily than other states of matter", false]], "q": "Why is fluorine more reactive than chlorine?", "wrong_explanations": {"1": "Fewer electrons in an outer shell means the atom needs to GAIN electrons \u2014 but that doesn't directly explain why fluorine attracts electrons more strongly. The distance from the nucleus is the key factor.", "2": "Fluorine does have fewer protons (9) than chlorine (17) \u2014 but its outer shell is MUCH closer to those protons. The closeness wins over the fewer-proton effect.", "3": "Chlorine is also a gas \u2014 being a gas is not the reason fluorine is more reactive."}}, {"opts": [["No reaction \u2014 iodine is less reactive than chlorine and cannot displace it", true], ["Chlorine gas is released \u2014 iodine displaces chloride ions", false], ["A brown precipitate forms \u2014 iodine reacts with sodium ions", false], ["The solution turns pale yellow \u2014 iodine bleaches the solution", false]], "q": "Iodine solution is added to sodium chloride solution. What happens?", "wrong_explanations": {"1": "A more reactive halogen displaces a less reactive one. Iodine is LESS reactive than chlorine \u2014 so iodine cannot displace chloride ions.", "2": "Iodine does not react with sodium ions \u2014 and even if it tried to displace chloride, it couldn't because iodine is less reactive than chlorine.", "3": "Iodine actually turns starch blue-black \u2014 it doesn't bleach. Chlorine is the halogen with bleaching properties."}}], "TH": [{"opts": [["The solution turns orange/brown \u2014 chlorine displaces bromide ions, releasing bromine", true], ["No change \u2014 chlorine cannot react with bromide ions", false], ["The solution turns pale green \u2014 chlorine is absorbed by the solution", false], ["A white precipitate forms \u2014 chlorine reacts with potassium ions", false]], "q": "Chlorine water is added to a solution of potassium bromide. What is observed?", "wrong_explanations": {"1": "Chlorine IS more reactive than bromine and CAN displace bromide \u2014 so a reaction does occur.", "2": "Chlorine water has a yellow-green colour but when it reacts with bromide, the BROWN colour of bromine is what appears in the solution.", "3": "Chlorine does not react with potassium ions \u2014 it displaces bromide ions. No precipitate forms."}}, {"opts": [["Fluorine is a smaller atom \u2014 its outer shell is closer to the nucleus, so it attracts an incoming electron more strongly", true], ["Fluorine has fewer electrons, making it less stable and more reactive", false], ["Fluorine has more protons, making its positive charge stronger", false], ["Fluorine is a gas, making it react more easily than other states of matter", false]], "q": "Why is fluorine more reactive than chlorine?", "wrong_explanations": {"1": "Fewer electrons in an outer shell means the atom needs to GAIN electrons \u2014 but that doesn't directly explain why fluorine attracts electrons more strongly. The distance from the nucleus is the key factor.", "2": "Fluorine does have fewer protons (9) than chlorine (17) \u2014 but its outer shell is MUCH closer to those protons. The closeness wins over the fewer-proton effect.", "3": "Chlorine is also a gas \u2014 being a gas is not the reason fluorine is more reactive."}}, {"opts": [["No reaction \u2014 iodine is less reactive than chlorine and cannot displace it", true], ["Chlorine gas is released \u2014 iodine displaces chloride ions", false], ["A brown precipitate forms \u2014 iodine reacts with sodium ions", false], ["The solution turns pale yellow \u2014 iodine bleaches the solution", false]], "q": "Iodine solution is added to sodium chloride solution. What happens?", "wrong_explanations": {"1": "A more reactive halogen displaces a less reactive one. Iodine is LESS reactive than chlorine \u2014 so iodine cannot displace chloride ions.", "2": "Iodine does not react with sodium ions \u2014 and even if it tried to displace chloride, it couldn't because iodine is less reactive than chlorine.", "3": "Iodine actually turns starch blue-black \u2014 it doesn't bleach. Chlorine is the halogen with bleaching properties."}}]}, "summary": "Describe the properties of halogens and explain trends in reactivity down Group 7.", "theory": [{"content": "GROUP 7 contains the HALOGENS:\nFluorine (F) \u2014 pale yellow gas.\nChlorine (Cl) \u2014 yellow-green gas.\nBromine (Br) \u2014 red-brown liquid.\nIodine (I) \u2014 grey-black solid (purple vapour).\nAstatine (At) \u2014 radioactive, very rare.\n\nAll Group 7 elements:\nHave 7 OUTER ELECTRONS \u2014 they gain ONE electron to form \u22121 ions (halide ions: F\u207b, Cl\u207b, Br\u207b, I\u207b).\nExist as DIATOMIC MOLECULES \u2014 F\u2082, Cl\u2082, Br\u2082, I\u2082 (each molecule is two atoms bonded together).\nAre NON-METALS \u2014 poor conductors, low melting/boiling points (except iodine which is a solid).\nReact with metals to form SALTS (compounds containing halide ions) \u2014 hence 'halogens' means 'salt-forming'.\nAre TOXIC \u2014 they are all poisonous in varying degrees.", "heading": "Properties of the Halogens"}, {"content": "Going DOWN Group 7 (F \u2192 Cl \u2192 Br \u2192 I):\n\nPHYSICAL TRENDS:\nMELTING AND BOILING POINT INCREASE:\nF\u2082: \u2212188\u00b0C, Cl\u2082: \u2212101\u00b0C, Br\u2082: 59\u00b0C, I\u2082: 184\u00b0C.\nLarger molecules \u2192 stronger London dispersion forces \u2192 higher boiling point.\n\nCOLOUR BECOMES DARKER:\nFluorine: pale yellow, Chlorine: yellow-green, Bromine: red-brown, Iodine: grey-black.\n\nCHEMICAL TREND:\nREACTIVITY DECREASES going down \u2014 OPPOSITE to Group 1.\n\nFluorine is the MOST REACTIVE non-metal known.\nIodine is much less reactive.\n\nWhy reactivity decreases:\nGoing down, atoms get LARGER \u2014 more electron shells.\nThe outer shell (where the incoming electron goes) is further from the nucleus.\nWeaker attraction for an incoming electron \u2192 less easily gained \u2192 less reactive.", "heading": "Physical and Chemical Trends Down Group 7"}, {"content": "A MORE REACTIVE halogen will DISPLACE a LESS REACTIVE halogen from its salt solution.\n\nThis demonstrates the reactivity order: F > Cl > Br > I.\n\nEXAMPLES:\nChlorine water + sodium bromide solution:\nCl\u2082 + 2NaBr \u2192 2NaCl + Br\u2082\nColour change: colourless \u2192 orange/brown (bromine appears).\nChlorine DISPLACES bromine because Cl is more reactive than Br.\n\nChlorine water + potassium iodide solution:\nCl\u2082 + 2KI \u2192 2KCl + I\u2082\nColour change: colourless \u2192 brown (iodine appears).\n\nBromine water + potassium iodide solution:\nBr\u2082 + 2KI \u2192 2KBr + I\u2082\nBromine displaces iodine \u2014 bromine is more reactive than iodine.\n\nNO REACTION: bromine water + sodium chloride \u2014 bromine CANNOT displace chlorine as Cl is more reactive.\n\nOIL LAYER TRICK: Add a non-polar solvent (e.g. cyclohexane) which forms a separate layer \u2014 iodine in the oil layer turns VIOLET/PURPLE, bromine turns ORANGE.", "heading": "Displacement Reactions of Halogens"}]};
window.KS4SRC["transition-metals"] = {"common_mistake": "Transition metals have HIGH melting points, HIGH density and are HARD \u2014 the opposite of Group 1. Group 1 are soft, low melting point, low density and very reactive. Don't confuse their properties. Mercury is the exception among transition metals \u2014 it is a liquid at room temperature.", "higher": "Write balanced ionic equations for reactions of transition metals and their compounds. Explain variable oxidation states in terms of d-electron configuration \u2014 transition metals can lose different numbers of electrons from the 3d and 4s subshells. Calculate the oxidation state of a transition metal from a compound formula. Evaluate the use of specific transition metals as catalysts with reference to their variable oxidation states.", "key_note": "Transition metals vs Group 1: higher melting point, higher density, harder, much less reactive. Typical properties: coloured compounds, catalytic activity, variable oxidation states, high strength. Key examples: iron (Haber process catalyst, steel), copper (wiring), nickel (hydrogenation), platinum (catalytic converters).", "matching": {"instruction": "Match each property to transition metals, Group 1 metals, or both.", "pairs": [["Transition metals", "High melting point, high density, hard and strong"], ["Group 1 metals", "Low melting point, low density, soft and very reactive with water"], ["Transition metals", "Form coloured compounds \u2014 e.g. copper sulfate (blue), iron(III) chloride (yellow)"], ["Transition metals", "Can act as catalysts \u2014 iron in Haber process, platinum in catalytic converters"], ["Transition metals", "Variable oxidation states \u2014 e.g. iron can be Fe\u00b2\u207a or Fe\u00b3\u207a"]], "title": "Transition Metal Properties"}, "quiz": {"TF": [{"opts": [["Transition metals have high melting points, high density and high strength \u2014 Group 1 metals are soft, low-density and too reactive for structural use", true], ["Transition metals are cheaper than Group 1 metals \u2014 cost makes them more practical", false], ["Group 1 metals are radioactive \u2014 too dangerous for use in buildings", false], ["Transition metals are lighter than Group 1 metals \u2014 easier to work with structurally", false]], "q": "Why are transition metals more useful as structural materials than Group 1 metals?", "wrong_explanations": {"1": "Cost is a practical factor but not the reason given in chemistry. The key reasons are mechanical properties: strength, hardness, melting point.", "2": "Group 1 metals (lithium, sodium, potassium etc.) are NOT radioactive \u2014 they are just very reactive with water and oxygen, making them unsuitable for structural use.", "3": "Transition metals are actually DENSER (heavier) than Group 1 metals \u2014 the advantages are strength and chemical stability, not lower weight."}}, {"opts": [["Iron \u2014 it acts as a catalyst to speed up the reaction between nitrogen and hydrogen", true], ["Copper \u2014 widely used catalyst in many industrial processes", false], ["Platinum \u2014 the most effective transition metal catalyst", false], ["Nickel \u2014 used in all industrial catalytic processes", false]], "q": "Which transition metal is used as a catalyst in the Haber process to manufacture ammonia?", "wrong_explanations": {"1": "Copper is a good conductor but not the catalyst used in the Haber process.", "2": "Platinum is used in catalytic converters for car exhaust and in the Contact process \u2014 not the Haber process.", "3": "Nickel is used in hydrogenation of vegetable oils \u2014 not the Haber process."}}], "TH": [{"opts": [["Transition metals have high melting points, high density and high strength \u2014 Group 1 metals are soft, low-density and too reactive for structural use", true], ["Transition metals are cheaper than Group 1 metals \u2014 cost makes them more practical", false], ["Group 1 metals are radioactive \u2014 too dangerous for use in buildings", false], ["Transition metals are lighter than Group 1 metals \u2014 easier to work with structurally", false]], "q": "Why are transition metals more useful as structural materials than Group 1 metals?", "wrong_explanations": {"1": "Cost is a practical factor but not the reason given in chemistry. The key reasons are mechanical properties: strength, hardness, melting point.", "2": "Group 1 metals (lithium, sodium, potassium etc.) are NOT radioactive \u2014 they are just very reactive with water and oxygen, making them unsuitable for structural use.", "3": "Transition metals are actually DENSER (heavier) than Group 1 metals \u2014 the advantages are strength and chemical stability, not lower weight."}}, {"opts": [["Iron \u2014 it acts as a catalyst to speed up the reaction between nitrogen and hydrogen", true], ["Copper \u2014 widely used catalyst in many industrial processes", false], ["Platinum \u2014 the most effective transition metal catalyst", false], ["Nickel \u2014 used in all industrial catalytic processes", false]], "q": "Which transition metal is used as a catalyst in the Haber process to manufacture ammonia?", "wrong_explanations": {"1": "Copper is a good conductor but not the catalyst used in the Haber process.", "2": "Platinum is used in catalytic converters for car exhaust and in the Contact process \u2014 not the Haber process.", "3": "Nickel is used in hydrogenation of vegetable oils \u2014 not the Haber process."}}]}, "summary": "Compare transition metals with Group 1 metals and describe their typical properties and uses.", "theory": [{"content": "Transition metals occupy the central block of the periodic table (periods 4\u20136, groups 3\u201312).\n\nCommon examples: iron (Fe), copper (Cu), zinc (Zn), chromium (Cr), titanium (Ti), nickel (Ni), cobalt (Co), gold (Au), silver (Ag), platinum (Pt).\n\nCOMPARISON WITH GROUP 1 (ALKALI METALS):\n\nProperty | Transition metals | Group 1 metals\nMelting point | HIGH (e.g. iron 1538\u00b0C) | LOW (e.g. sodium 98\u00b0C)\nDensity | HIGH (e.g. iron 7.8 g/cm\u00b3) | LOW (e.g. lithium 0.5 g/cm\u00b3)\nHardness | HARD and strong | SOFT (can be cut with a knife)\nReactivity with water | LOW or none | HIGH (vigorous reaction)\nReactivity with oxygen | LOW (often need heating) | HIGH (rapidly tarnish or burn)\nStrength | High tensile strength | Low strength\n\nGroup 1 metals are so reactive they must be stored under oil to prevent oxidation.\nTransition metals are generally much less reactive and much more mechanically useful.", "heading": "Comparing Transition Metals with Group 1"}, {"content": "Transition metals share several characteristic properties:\n\n1. HIGH DENSITY AND HARDNESS:\nMuch denser and harder than Group 1 metals.\nMakes them useful as structural materials.\nIron: used in construction, steel-making.\nTitanium: extremely strong and light, used in aircraft.\n\n2. HIGH MELTING POINTS:\nMost transition metals have melting points above 1000\u00b0C.\nException: mercury (Hg) is a liquid at room temperature.\nMakes them suitable for high-temperature applications.\n\n3. FORM COLOURED COMPOUNDS:\nTransition metal ions produce characteristically coloured compounds and solutions.\nCopper(II) sulfate: blue. Iron(II) sulfate: pale green. Iron(III) chloride: yellow/brown.\nPotassium manganate(VII): purple. Potassium dichromate: orange.\nThis colour arises from the d-electrons of the transition metal ion.\n\n4. ACT AS CATALYSTS:\nTransition metals and their compounds are widely used as catalysts.\nIron: catalyst in Haber process (making ammonia).\nNickel: catalyst in hydrogenation of vegetable oils (making margarine).\nPlatinum/rhodium: catalytic converters in car exhaust systems.\nManganese(IV) oxide: catalyst for decomposition of hydrogen peroxide.\nVanadium(V) oxide: catalyst in Contact process (making sulfuric acid).\n\n5. VARIABLE OXIDATION STATES:\nTransition metals can form ions with different charges.\nIron: Fe\u00b2\u207a (iron(II)) and Fe\u00b3\u207a (iron(III)).\nCopper: Cu\u207a (copper(I)) and Cu\u00b2\u207a (copper(II)).\nManganese: Mn\u00b2\u207a, Mn\u2074\u207a, Mn\u2077\u207a (in permanganate).\nThis is why they can act as effective catalysts \u2014 they can change oxidation state during a reaction.", "heading": "Typical Properties of Transition Metals"}, {"content": "The properties of transition metals make them essential materials:\n\nIRON AND STEEL:\nIron is the most widely used transition metal.\nPure iron is soft \u2014 alloyed with carbon and other elements to make steel.\nSteel: high tensile strength, used in construction, vehicles, tools.\nStainless steel (with chromium and nickel): rust-resistant, used in cutlery and surgical instruments.\n\nCOPPER:\nGood electrical and thermal conductor.\nUsed in electrical wiring, plumbing pipes, heat exchangers.\nCopper alloys: bronze (Cu + Sn), brass (Cu + Zn).\n\nTITANIUM:\nVery strong, low density, excellent corrosion resistance.\nUsed in aircraft, spacecraft, artificial joints, dental implants.\n\nNICKEL:\nCatalyst in food industry (hydrogenation of oils).\nUsed in alloys (stainless steel, nichrome heating wire).\n\nPLATINUM:\nExcellent catalyst \u2014 catalytic converters, laboratory catalysts.\nJewellery \u2014 resistant to corrosion.\n\nGOLD AND SILVER:\nResistant to corrosion \u2014 jewellery, electrical contacts, photography.", "heading": "Uses of Transition Metals"}]};
window.KS4SRC["mass-changes-reactions"] = {"common_mistake": "When a metal burns in air, the solid GAINS mass (oxygen is added from the air to form the oxide). Students often expect the solid to lose mass because 'burning destroys things' \u2014 but mass is always conserved. The apparent gain is real because you are adding oxygen from the atmosphere to the solid product.", "fifas": [{"label": "Mass Change Prediction", "question": "4.8 g of magnesium burns completely in air: 2Mg + O\u2082 \u2192 2MgO. Calculate the mass of MgO produced. Ar: Mg=24, O=16.", "steps": [["F", "Use ratio from balanced equation: 2 \u00d7 Mr(Mg) : 2 \u00d7 Mr(MgO) = 48 : 80"], ["I", "Scale: 4.8 g of Mg. Scale factor = 4.8 \u00f7 48 = 0.1"], ["F", "Mass of MgO = 80 \u00d7 0.1 = 8.0 g"], ["A", "8.0 g of MgO produced (mass increases by 3.2 g \u2014 the absorbed oxygen)"]]}], "key_note": "Mass is always conserved. Apparent decrease: gas escapes (e.g. CO\u2082 from acid + carbonate). Apparent increase: gas absorbed from air (e.g. O\u2082 absorbed when Mg burns). Closed container: mass always stays the same. Look for gases when mass appears to change.", "matching": {"instruction": "Predict what happens to the measured mass in each scenario.", "pairs": [["Mass decreases", "CaCO\u2083 + HCl in an open flask \u2014 CO\u2082 gas escapes into the atmosphere"], ["Mass increases", "Magnesium burning in air \u2014 oxygen from air absorbed into MgO solid product"], ["Mass stays same", "Precipitation reaction in a sealed flask \u2014 no gas escapes or enters"], ["Mass decreases", "Zinc + sulfuric acid in an open tube \u2014 H\u2082 gas escapes"], ["Mass stays same", "CaCO\u2083 heated in a sealed tube \u2014 CO\u2082 trapped inside"]], "title": "Mass Increases, Decreases or Stays Same?"}, "quiz": {"CF": [{"opts": [["The mass decreases \u2014 CO\u2082 gas escapes from the open crucible", true], ["The mass increases \u2014 oxygen from air is absorbed", false], ["The mass stays the same \u2014 conservation of mass", false], ["The mass first increases, then decreases", false]], "q": "A student heats calcium carbonate in an open crucible. CaCO\u2083 \u2192 CaO + CO\u2082. What happens to the measured mass?", "wrong_explanations": {"1": "Oxygen is not absorbed here \u2014 CaCO\u2083 is decomposing, not combusting. A gas (CO\u2082) is PRODUCED and escapes.", "2": "Conservation of mass applies to the TOTAL system. In an open container, the mass of the CONTAINER contents decreases because CO\u2082 leaves. Conservation is still upheld if you include the escaped CO\u2082.", "3": "There is no initial increase phase \u2014 CO\u2082 is produced and escapes from the start of heating."}}, {"opts": [["Oxygen from the air combines with the iron \u2014 the oxygen adds to the mass of the solid product (iron oxide)", true], ["Water from humidity condenses on the rust \u2014 adding extra mass", false], ["The iron becomes denser as it rusts \u2014 same volume but more mass", false], ["Iron oxide has more atoms per formula unit than iron", false]], "q": "Why does the mass of iron increase when it rusts in air?", "wrong_explanations": {"1": "Humidity can contribute, but the primary reason is oxygen being ABSORBED from the air. The reaction is 4Fe + 3O\u2082 \u2192 2Fe\u2082O\u2083 \u2014 the oxygen becomes part of the solid.", "2": "Density changes do not increase total mass \u2014 mass = density \u00d7 volume. If both change proportionally, mass stays the same. More mass comes from more matter (oxygen absorbed).", "3": "Atom count per formula unit is irrelevant \u2014 it is the MASS of oxygen absorbed from air that increases the total mass."}}], "CH": [{"opts": [["The mass decreases \u2014 CO\u2082 gas escapes from the open crucible", true], ["The mass increases \u2014 oxygen from air is absorbed", false], ["The mass stays the same \u2014 conservation of mass", false], ["The mass first increases, then decreases", false]], "q": "A student heats calcium carbonate in an open crucible. CaCO\u2083 \u2192 CaO + CO\u2082. What happens to the measured mass?", "wrong_explanations": {"1": "Oxygen is not absorbed here \u2014 CaCO\u2083 is decomposing, not combusting. A gas (CO\u2082) is PRODUCED and escapes.", "2": "Conservation of mass applies to the TOTAL system. In an open container, the mass of the CONTAINER contents decreases because CO\u2082 leaves. Conservation is still upheld if you include the escaped CO\u2082.", "3": "There is no initial increase phase \u2014 CO\u2082 is produced and escapes from the start of heating."}}, {"opts": [["Oxygen from the air combines with the iron \u2014 the oxygen adds to the mass of the solid product (iron oxide)", true], ["Water from humidity condenses on the rust \u2014 adding extra mass", false], ["The iron becomes denser as it rusts \u2014 same volume but more mass", false], ["Iron oxide has more atoms per formula unit than iron", false]], "q": "Why does the mass of iron increase when it rusts in air?", "wrong_explanations": {"1": "Humidity can contribute, but the primary reason is oxygen being ABSORBED from the air. The reaction is 4Fe + 3O\u2082 \u2192 2Fe\u2082O\u2083 \u2014 the oxygen becomes part of the solid.", "2": "Density changes do not increase total mass \u2014 mass = density \u00d7 volume. If both change proportionally, mass stays the same. More mass comes from more matter (oxygen absorbed).", "3": "Atom count per formula unit is irrelevant \u2014 it is the MASS of oxygen absorbed from air that increases the total mass."}}], "TF": [{"opts": [["The mass decreases \u2014 CO\u2082 gas escapes from the open crucible", true], ["The mass increases \u2014 oxygen from air is absorbed", false], ["The mass stays the same \u2014 conservation of mass", false], ["The mass first increases, then decreases", false]], "q": "A student heats calcium carbonate in an open crucible. CaCO\u2083 \u2192 CaO + CO\u2082. What happens to the measured mass?", "wrong_explanations": {"1": "Oxygen is not absorbed here \u2014 CaCO\u2083 is decomposing, not combusting. A gas (CO\u2082) is PRODUCED and escapes.", "2": "Conservation of mass applies to the TOTAL system. In an open container, the mass of the CONTAINER contents decreases because CO\u2082 leaves. Conservation is still upheld if you include the escaped CO\u2082.", "3": "There is no initial increase phase \u2014 CO\u2082 is produced and escapes from the start of heating."}}, {"opts": [["Oxygen from the air combines with the iron \u2014 the oxygen adds to the mass of the solid product (iron oxide)", true], ["Water from humidity condenses on the rust \u2014 adding extra mass", false], ["The iron becomes denser as it rusts \u2014 same volume but more mass", false], ["Iron oxide has more atoms per formula unit than iron", false]], "q": "Why does the mass of iron increase when it rusts in air?", "wrong_explanations": {"1": "Humidity can contribute, but the primary reason is oxygen being ABSORBED from the air. The reaction is 4Fe + 3O\u2082 \u2192 2Fe\u2082O\u2083 \u2014 the oxygen becomes part of the solid.", "2": "Density changes do not increase total mass \u2014 mass = density \u00d7 volume. If both change proportionally, mass stays the same. More mass comes from more matter (oxygen absorbed).", "3": "Atom count per formula unit is irrelevant \u2014 it is the MASS of oxygen absorbed from air that increases the total mass."}}], "TH": [{"opts": [["The mass decreases \u2014 CO\u2082 gas escapes from the open crucible", true], ["The mass increases \u2014 oxygen from air is absorbed", false], ["The mass stays the same \u2014 conservation of mass", false], ["The mass first increases, then decreases", false]], "q": "A student heats calcium carbonate in an open crucible. CaCO\u2083 \u2192 CaO + CO\u2082. What happens to the measured mass?", "wrong_explanations": {"1": "Oxygen is not absorbed here \u2014 CaCO\u2083 is decomposing, not combusting. A gas (CO\u2082) is PRODUCED and escapes.", "2": "Conservation of mass applies to the TOTAL system. In an open container, the mass of the CONTAINER contents decreases because CO\u2082 leaves. Conservation is still upheld if you include the escaped CO\u2082.", "3": "There is no initial increase phase \u2014 CO\u2082 is produced and escapes from the start of heating."}}, {"opts": [["Oxygen from the air combines with the iron \u2014 the oxygen adds to the mass of the solid product (iron oxide)", true], ["Water from humidity condenses on the rust \u2014 adding extra mass", false], ["The iron becomes denser as it rusts \u2014 same volume but more mass", false], ["Iron oxide has more atoms per formula unit than iron", false]], "q": "Why does the mass of iron increase when it rusts in air?", "wrong_explanations": {"1": "Humidity can contribute, but the primary reason is oxygen being ABSORBED from the air. The reaction is 4Fe + 3O\u2082 \u2192 2Fe\u2082O\u2083 \u2014 the oxygen becomes part of the solid.", "2": "Density changes do not increase total mass \u2014 mass = density \u00d7 volume. If both change proportionally, mass stays the same. More mass comes from more matter (oxygen absorbed).", "3": "Atom count per formula unit is irrelevant \u2014 it is the MASS of oxygen absorbed from air that increases the total mass."}}]}, "summary": "Explain why the measured mass sometimes appears to change in a reaction and predict mass changes.", "theory": [{"content": "Conservation of mass tells us total mass never changes. Yet in some experiments, the MEASURED mass appears to increase or decrease. This is NOT a violation of conservation of mass \u2014 it is because a GAS enters or leaves the reaction vessel.\n\nWHEN MASS APPEARS TO DECREASE:\nA GAS is PRODUCED and escapes into the atmosphere.\nThe gas molecules leave the container and are no longer weighed.\nExample: CaCO\u2083(s) + 2HCl(aq) \u2192 CaCl\u2082(aq) + H\u2082O(l) + CO\u2082(g)\nCO\u2082 gas escapes \u2192 measured mass decreases.\nExample: Mg ribbon burning \u2014 ash (MgO) seems lighter than the ribbon, but this is because oxygen from AIR was added. Without accounting for the oxygen, mass appears lost.\n\nWHEN MASS APPEARS TO INCREASE:\nA GAS is ABSORBED or ADDED from the atmosphere.\nExample: Magnesium burning in air:\n2Mg(s) + O\u2082(g) \u2192 2MgO(s)\nOxygen from the air is absorbed into the solid product \u2192 measured mass of solid INCREASES.\nThe oxygen molecules join the solid \u2014 weighed mass goes up.", "heading": "When Mass Appears to Change"}, {"content": "You can predict mass changes using the balanced equation and Mr values.\n\nIF A GAS IS PRODUCED and escapes an open container:\nMass of container decreases by mass of gas produced.\n\nIF A GAS IS ABSORBED from the air:\nMass of solid/container increases by mass of gas absorbed.\n\nExample calculation:\n2Mg + O\u2082 \u2192 2MgO\nMr values: Mg = 24, O\u2082 = 32, MgO = 40\n\nIf 4.8 g of Mg burns completely in air:\nMoles of Mg = 4.8 \u00f7 24 = 0.2 mol\nFrom equation: 2 mol Mg needs 1 mol O\u2082, so 0.2 mol Mg needs 0.1 mol O\u2082\nMass of O\u2082 absorbed = 0.1 \u00d7 32 = 3.2 g\nMass increase = 3.2 g (the oxygen from air added to the solid)\nExpected mass of MgO = 4.8 + 3.2 = 8.0 g\n\nCheck: 0.2 mol MgO \u00d7 40 = 8.0 g \u2713", "heading": "Predicting Mass Changes"}, {"content": "Students sometimes observe apparent non-conservation \u2014 these all have explanations:\n\nPRECIPITATION REACTIONS in closed containers:\nNo gas escapes or enters \u2192 mass stays exactly the same. \u2713\n\nHEATING A METAL IN AIR (open container):\nMass INCREASES \u2014 oxygen from air is absorbed.\nIf weighed in a closed container with air, mass stays constant (oxygen absorbed from sealed air pocket).\n\nDECOMPOSITION reactions producing gas (e.g. CaCO\u2083 \u2192 CaO + CO\u2082):\nIn open container: mass DECREASES (CO\u2082 escapes).\nIn closed container: mass stays constant (CO\u2082 trapped).\n\nBURNING HYDROCARBONS in open container:\nCO\u2082 and H\u2082O vapour escape \u2192 apparent mass decreases.\n\nKEY INSIGHT: If you cannot account for a mass change, look for a gas being produced or absorbed \u2014 conservation of mass is ALWAYS upheld in the universe, even if your experiment doesn't show it.", "heading": "Non-conservation Apparent Effects"}]};
window.KS4SRC["chemical-measurements"] = {"common_mistake": "Read the volume from the BOTTOM of the meniscus \u2014 not the top. Water curves downward in a glass tube, creating a concave meniscus. Reading from the top overestimates the volume. Also: zeroing the balance (taring) before each measurement is essential \u2014 failing to do so introduces a systematic error.", "equations": ["% uncertainty = (uncertainty \u00f7 measured value) \u00d7 100"], "fifas": [{"label": "Percentage Uncertainty", "question": "A student measures 25.0 cm\u00b3 of solution using a measuring cylinder with an uncertainty of \u00b10.5 cm\u00b3. Calculate the percentage uncertainty.", "steps": [["F", "% uncertainty = (uncertainty \u00f7 measured value) \u00d7 100"], ["I", "% uncertainty = (0.5 \u00f7 25.0) \u00d7 100"], ["F", "% uncertainty = 0.02 \u00d7 100"], ["A", "% uncertainty = 2.0%"]]}], "key_note": "Accuracy: how close to true value. Precision: how reproducible. Burette: \u00b10.05 cm\u00b3 \u2014 most precise for volumes. Pipette: exact fixed volume. Read from bottom of meniscus at eye level. % uncertainty = (uncertainty \u00f7 measured value) \u00d7 100. Larger measurement \u2192 smaller % uncertainty.", "matching": {"instruction": "Match each piece of equipment to its use and precision.", "pairs": [["Burette", "Accurately delivers variable volumes of solution \u2014 read to \u00b10.05 cm\u00b3 \u2014 used in titrations"], ["Pipette", "Delivers one precise fixed volume \u2014 e.g. exactly 25.00 cm\u00b3 of solution"], ["Measuring cylinder", "Less precise volume measurement \u2014 read from bottom of meniscus"], ["Digital balance", "Measures mass precisely \u2014 typically \u00b10.01 g \u2014 zero before each use"], ["Thermometer", "Measures temperature \u2014 typically \u00b10.5\u00b0C or \u00b11\u00b0C"]], "title": "Match the Measuring Equipment"}, "quiz": {"CF": [{"opts": [["The burette \u2014 % uncertainty = (0.05 \u00f7 25) \u00d7 100 = 0.2%, vs the cylinder at 4%", true], ["The measuring cylinder \u2014 larger equipment is always more accurate", false], ["They are the same \u2014 both deliver 25 cm\u00b3", false], ["The measuring cylinder \u2014 it has a smaller absolute uncertainty", false]], "q": "A student measures a volume using a burette and a measuring cylinder. The burette has an uncertainty of \u00b10.05 cm\u00b3 and the cylinder \u00b11 cm\u00b3. Both deliver 25 cm\u00b3. Which gives the lower percentage uncertainty?", "wrong_explanations": {"1": "Equipment size doesn't determine accuracy \u2014 precision depends on the uncertainty relative to the measurement.", "2": "Both deliver the same VOLUME but with different UNCERTAINTIES \u2014 the burette (\u00b10.05) is far more precise than the measuring cylinder (\u00b11).", "3": "The measuring cylinder has a LARGER absolute uncertainty (\u00b11 cm\u00b3 vs \u00b10.05 cm\u00b3) \u2014 it is LESS precise, not more."}}, {"opts": [["From the bottom of the meniscus \u2014 water curves downward, creating a concave surface", true], ["From the top of the meniscus \u2014 this gives the largest volume reading", false], ["From the middle of the meniscus \u2014 splitting the difference", false], ["It doesn't matter \u2014 the meniscus reading is always correct", false]], "q": "When reading a burette or measuring cylinder containing water, where should you read the volume?", "wrong_explanations": {"1": "Reading from the TOP of the meniscus gives an overestimate \u2014 the markings are calibrated for the bottom of the meniscus.", "2": "Reading from the middle introduces error \u2014 always read from the BOTTOM consistently to match calibration.", "3": "Reading from the wrong part of the meniscus introduces a systematic error \u2014 it DOES matter and affects accuracy."}}], "CH": [{"opts": [["The burette \u2014 % uncertainty = (0.05 \u00f7 25) \u00d7 100 = 0.2%, vs the cylinder at 4%", true], ["The measuring cylinder \u2014 larger equipment is always more accurate", false], ["They are the same \u2014 both deliver 25 cm\u00b3", false], ["The measuring cylinder \u2014 it has a smaller absolute uncertainty", false]], "q": "A student measures a volume using a burette and a measuring cylinder. The burette has an uncertainty of \u00b10.05 cm\u00b3 and the cylinder \u00b11 cm\u00b3. Both deliver 25 cm\u00b3. Which gives the lower percentage uncertainty?", "wrong_explanations": {"1": "Equipment size doesn't determine accuracy \u2014 precision depends on the uncertainty relative to the measurement.", "2": "Both deliver the same VOLUME but with different UNCERTAINTIES \u2014 the burette (\u00b10.05) is far more precise than the measuring cylinder (\u00b11).", "3": "The measuring cylinder has a LARGER absolute uncertainty (\u00b11 cm\u00b3 vs \u00b10.05 cm\u00b3) \u2014 it is LESS precise, not more."}}, {"opts": [["From the bottom of the meniscus \u2014 water curves downward, creating a concave surface", true], ["From the top of the meniscus \u2014 this gives the largest volume reading", false], ["From the middle of the meniscus \u2014 splitting the difference", false], ["It doesn't matter \u2014 the meniscus reading is always correct", false]], "q": "When reading a burette or measuring cylinder containing water, where should you read the volume?", "wrong_explanations": {"1": "Reading from the TOP of the meniscus gives an overestimate \u2014 the markings are calibrated for the bottom of the meniscus.", "2": "Reading from the middle introduces error \u2014 always read from the BOTTOM consistently to match calibration.", "3": "Reading from the wrong part of the meniscus introduces a systematic error \u2014 it DOES matter and affects accuracy."}}], "TF": [{"opts": [["The burette \u2014 % uncertainty = (0.05 \u00f7 25) \u00d7 100 = 0.2%, vs the cylinder at 4%", true], ["The measuring cylinder \u2014 larger equipment is always more accurate", false], ["They are the same \u2014 both deliver 25 cm\u00b3", false], ["The measuring cylinder \u2014 it has a smaller absolute uncertainty", false]], "q": "A student measures a volume using a burette and a measuring cylinder. The burette has an uncertainty of \u00b10.05 cm\u00b3 and the cylinder \u00b11 cm\u00b3. Both deliver 25 cm\u00b3. Which gives the lower percentage uncertainty?", "wrong_explanations": {"1": "Equipment size doesn't determine accuracy \u2014 precision depends on the uncertainty relative to the measurement.", "2": "Both deliver the same VOLUME but with different UNCERTAINTIES \u2014 the burette (\u00b10.05) is far more precise than the measuring cylinder (\u00b11).", "3": "The measuring cylinder has a LARGER absolute uncertainty (\u00b11 cm\u00b3 vs \u00b10.05 cm\u00b3) \u2014 it is LESS precise, not more."}}, {"opts": [["From the bottom of the meniscus \u2014 water curves downward, creating a concave surface", true], ["From the top of the meniscus \u2014 this gives the largest volume reading", false], ["From the middle of the meniscus \u2014 splitting the difference", false], ["It doesn't matter \u2014 the meniscus reading is always correct", false]], "q": "When reading a burette or measuring cylinder containing water, where should you read the volume?", "wrong_explanations": {"1": "Reading from the TOP of the meniscus gives an overestimate \u2014 the markings are calibrated for the bottom of the meniscus.", "2": "Reading from the middle introduces error \u2014 always read from the BOTTOM consistently to match calibration.", "3": "Reading from the wrong part of the meniscus introduces a systematic error \u2014 it DOES matter and affects accuracy."}}], "TH": [{"opts": [["The burette \u2014 % uncertainty = (0.05 \u00f7 25) \u00d7 100 = 0.2%, vs the cylinder at 4%", true], ["The measuring cylinder \u2014 larger equipment is always more accurate", false], ["They are the same \u2014 both deliver 25 cm\u00b3", false], ["The measuring cylinder \u2014 it has a smaller absolute uncertainty", false]], "q": "A student measures a volume using a burette and a measuring cylinder. The burette has an uncertainty of \u00b10.05 cm\u00b3 and the cylinder \u00b11 cm\u00b3. Both deliver 25 cm\u00b3. Which gives the lower percentage uncertainty?", "wrong_explanations": {"1": "Equipment size doesn't determine accuracy \u2014 precision depends on the uncertainty relative to the measurement.", "2": "Both deliver the same VOLUME but with different UNCERTAINTIES \u2014 the burette (\u00b10.05) is far more precise than the measuring cylinder (\u00b11).", "3": "The measuring cylinder has a LARGER absolute uncertainty (\u00b11 cm\u00b3 vs \u00b10.05 cm\u00b3) \u2014 it is LESS precise, not more."}}, {"opts": [["From the bottom of the meniscus \u2014 water curves downward, creating a concave surface", true], ["From the top of the meniscus \u2014 this gives the largest volume reading", false], ["From the middle of the meniscus \u2014 splitting the difference", false], ["It doesn't matter \u2014 the meniscus reading is always correct", false]], "q": "When reading a burette or measuring cylinder containing water, where should you read the volume?", "wrong_explanations": {"1": "Reading from the TOP of the meniscus gives an overestimate \u2014 the markings are calibrated for the bottom of the meniscus.", "2": "Reading from the middle introduces error \u2014 always read from the BOTTOM consistently to match calibration.", "3": "Reading from the wrong part of the meniscus introduces a systematic error \u2014 it DOES matter and affects accuracy."}}]}, "summary": "Describe the importance of precise measurements in chemistry and sources of uncertainty.", "theory": [{"content": "Quantitative chemistry relies on PRECISE and ACCURATE measurements.\n\nACCURACY \u2014 how close a measurement is to the TRUE value.\nPRECISION \u2014 how reproducible/consistent measurements are (close to each other).\n\nA measurement can be precise but not accurate (consistently wrong), or accurate but not precise (correct on average but variable).\n\nIn chemistry, measurements include:\nMASSES \u2014 measured using a balance (in grams, g).\nVOLUMES of solutions \u2014 measured using a burette, pipette or measuring cylinder (in cm\u00b3 or dm\u00b3).\nTEMPERATURES \u2014 measured using a thermometer (in \u00b0C).\nTIMES \u2014 measured using a stopwatch (in seconds).\n\nUnits matter enormously:\n1 dm\u00b3 = 1 litre = 1000 cm\u00b3\n1 cm\u00b3 = 0.001 dm\u00b3 = 1 mL", "heading": "Why Measurements Matter in Chemistry"}, {"content": "Every measurement has some UNCERTAINTY \u2014 a range within which the true value lies.\n\nSources of uncertainty:\nREADING ERROR \u2014 difficulty in reading exact values from scales (e.g. reading a burette between markings).\nSYSTEMATIC ERROR \u2014 a consistent bias in one direction (e.g. a balance not zeroed correctly, a calibration error).\nRANDOM ERROR \u2014 unpredictable variations that scatter measurements around the true value.\n\nReduce uncertainty by:\nUsing more precise equipment (e.g. a 25 cm\u00b3 pipette is more precise than a 100 cm\u00b3 measuring cylinder).\nTaking REPEAT measurements and calculating a MEAN.\nUsing appropriate measuring equipment for the scale of measurement.\n\nPercentage uncertainty = (uncertainty \u00f7 measured value) \u00d7 100\n\nThe percentage uncertainty of a small measurement is higher than that of a large measurement with the same absolute uncertainty \u2014 this is why measuring small volumes with a large cylinder is poor practice.", "heading": "Uncertainty in Measurements"}, {"content": "Common measuring equipment and their precision:\n\nBALANCE (digital): typically \u00b10.01 g or \u00b10.001 g \u2014 high precision.\n\nBURETTE: 50 cm\u00b3 burette with 0.1 cm\u00b3 markings. Read to \u00b10.05 cm\u00b3 (between markings). Used for accurate volume delivery in titrations.\n\nPIPETTE: fixed volume (e.g. exactly 25.00 cm\u00b3). Very high precision for delivering one specific volume. Used to deliver precise volumes of solutions.\n\nMEASURING CYLINDER: less precise than a burette or pipette. Read from the BOTTOM of the MENISCUS (the curved water surface).\n\nTHERMOMETER: typically \u00b11\u00b0C or \u00b10.5\u00b0C depending on type.\n\nKEY SKILLS:\nRead burettes and measuring cylinders at eye level to avoid PARALLAX ERROR.\nRead from the BOTTOM of the meniscus for water-based solutions.\nZero the balance before each measurement (tare).\nRepeat and average for reliability.", "heading": "Practical Measurement Techniques"}], "variables": [["% uncertainty", "Percentage uncertainty", "%", ""]]};
window.KS4SRC["moles"] = {"common_mistake": "Make sure mass is in GRAMS before dividing by Mr. If given mass in kg, multiply by 1000 first. Also: 1 mole of H\u2082O contains 6.02 \u00d7 10\u00b2\u00b3 MOLECULES \u2014 but 3 \u00d7 6.02 \u00d7 10\u00b2\u00b3 ATOMS (2 H + 1 O per molecule). Always be clear about what particles are being counted.", "equations": ["moles (mol) = mass (g) \u00f7 Mr", "mass (g) = moles (mol) \u00d7 Mr", "number of particles = moles \u00d7 6.02 \u00d7 10\u00b2\u00b3", "% mass = (Ar \u00d7 number of atoms \u00f7 Mr) \u00d7 100"], "fifas": [{"label": "Moles from Mass", "question": "Calculate the number of moles in 27 g of aluminium (Ar = 27).", "steps": [["F", "moles = mass \u00f7 Mr"], ["I", "moles = 27 \u00f7 27"], ["F", "moles = 1"], ["A", "1 mol of aluminium"]]}], "key_note": "1 mole = 6.02 \u00d7 10\u00b2\u00b3 particles (Avogadro constant). n = m \u00f7 Mr. The molar mass = Mr in g/mol. % mass = (Ar \u00d7 atoms \u00f7 Mr) \u00d7 100.", "matching": {"instruction": "Match each calculation to the correct answer.", "pairs": [["Moles in 40 g NaOH (Mr=40)", "1 mol \u2014 n = 40 \u00f7 40 = 1"], ["Mass of 2 mol CO\u2082 (Mr=44)", "88 g \u2014 mass = 2 \u00d7 44 = 88"], ["Moles in 5.6 g Fe (Ar=56)", "0.1 mol \u2014 n = 5.6 \u00f7 56 = 0.1"], ["Particles in 0.5 mol", "3.01 \u00d7 10\u00b2\u00b3 \u2014 0.5 \u00d7 6.02 \u00d7 10\u00b2\u00b3"], ["% mass of Ca in CaCO\u2083 (Mr=100)", "40% \u2014 (40 \u00f7 100) \u00d7 100 = 40%"]], "title": "Moles Calculations"}, "quiz": {"CH": [{"opts": [["0.1 mol \u2014 n = 9.8 \u00f7 98 = 0.1", true], ["10 mol \u2014 n = 98 \u00f7 9.8 = 10", false], ["960.4 mol \u2014 n = 9.8 \u00d7 98 = 960.4", false], ["0.01 mol \u2014 n = 9.8 \u00f7 980 = 0.01", false]], "q": "How many moles are in 9.8 g of sulfuric acid (H\u2082SO\u2084)? Mr = 98.", "wrong_explanations": {"1": "Dividing the WRONG way: n = mass \u00f7 Mr not Mr \u00f7 mass. n = 9.8 \u00f7 98 = 0.1 mol.", "2": "Multiplying mass and Mr gives a meaningless large number \u2014 always DIVIDE mass by Mr.", "3": "The Mr of H\u2082SO\u2084 is 98, not 980. n = 9.8 \u00f7 98 = 0.1 mol."}}, {"opts": [["50 g \u2014 3.01 \u00d7 10\u00b2\u00b3 \u00f7 6.02 \u00d7 10\u00b2\u00b3 = 0.5 mol; mass = 0.5 \u00d7 100 = 50 g", true], ["100 g \u2014 1 mole has mass 100 g regardless of particle count", false], ["30100 g \u2014 multiplying particle count by Mr", false], ["0.5 g \u2014 confusing moles with grams", false]], "q": "What mass of calcium carbonate (CaCO\u2083, Mr = 100) contains 3.01 \u00d7 10\u00b2\u00b3 formula units?", "wrong_explanations": {"1": "3.01 \u00d7 10\u00b2\u00b3 is HALF the Avogadro constant \u2014 so this represents 0.5 mol. Mass = 0.5 \u00d7 100 = 50 g.", "2": "The Mr gives mass PER MOLE \u2014 3.01 \u00d7 10\u00b2\u00b3 is only 0.5 mol, not 1 mol.", "3": "0.5 is the number of moles \u2014 multiply by Mr (100) to get mass: 0.5 \u00d7 100 = 50 g."}}], "TH": [{"opts": [["0.1 mol \u2014 n = 9.8 \u00f7 98 = 0.1", true], ["10 mol \u2014 n = 98 \u00f7 9.8 = 10", false], ["960.4 mol \u2014 n = 9.8 \u00d7 98 = 960.4", false], ["0.01 mol \u2014 n = 9.8 \u00f7 980 = 0.01", false]], "q": "How many moles are in 9.8 g of sulfuric acid (H\u2082SO\u2084)? Mr = 98.", "wrong_explanations": {"1": "Dividing the WRONG way: n = mass \u00f7 Mr not Mr \u00f7 mass. n = 9.8 \u00f7 98 = 0.1 mol.", "2": "Multiplying mass and Mr gives a meaningless large number \u2014 always DIVIDE mass by Mr.", "3": "The Mr of H\u2082SO\u2084 is 98, not 980. n = 9.8 \u00f7 98 = 0.1 mol."}}, {"opts": [["50 g \u2014 3.01 \u00d7 10\u00b2\u00b3 \u00f7 6.02 \u00d7 10\u00b2\u00b3 = 0.5 mol; mass = 0.5 \u00d7 100 = 50 g", true], ["100 g \u2014 1 mole has mass 100 g regardless of particle count", false], ["30100 g \u2014 multiplying particle count by Mr", false], ["0.5 g \u2014 confusing moles with grams", false]], "q": "What mass of calcium carbonate (CaCO\u2083, Mr = 100) contains 3.01 \u00d7 10\u00b2\u00b3 formula units?", "wrong_explanations": {"1": "3.01 \u00d7 10\u00b2\u00b3 is HALF the Avogadro constant \u2014 so this represents 0.5 mol. Mass = 0.5 \u00d7 100 = 50 g.", "2": "The Mr gives mass PER MOLE \u2014 3.01 \u00d7 10\u00b2\u00b3 is only 0.5 mol, not 1 mol.", "3": "0.5 is the number of moles \u2014 multiply by Mr (100) to get mass: 0.5 \u00d7 100 = 50 g."}}]}, "summary": "Define the mole, use the Avogadro constant and calculate moles from mass and Mr.", "theory": [{"content": "Atoms and molecules are far too small to count individually \u2014 there are billions of billions of them in even a tiny sample.\n\nChemists use the MOLE (symbol: mol) as a counting unit for particles.\n\nOne MOLE of any substance contains the SAME NUMBER of particles (atoms, molecules or ions):\n6.02 \u00d7 10\u00b2\u00b3 particles \u2014 this is the AVOGADRO CONSTANT (N\u2090).\n\nThis number is chosen because:\n1 mole of carbon-12 atoms has a mass of exactly 12 grams.\nSo 1 mole of any substance has a mass equal to its relative formula mass in grams.\n\nExamples:\n1 mole of water (H\u2082O, Mr = 18) has mass 18 g and contains 6.02 \u00d7 10\u00b2\u00b3 molecules.\n1 mole of NaCl (Mr = 58.5) has mass 58.5 g and contains 6.02 \u00d7 10\u00b2\u00b3 formula units.\n1 mole of Fe (Ar = 56) has mass 56 g and contains 6.02 \u00d7 10\u00b2\u00b3 atoms.", "heading": "The Mole \u2014 A Counting Unit for Chemistry"}, {"content": "The key equation linking moles, mass and Mr:\n\nmoles (mol) = mass (g) \u00f7 Mr\n\nRearranging:\nmass (g) = moles (mol) \u00d7 Mr\nMr = mass (g) \u00f7 moles (mol)\n\nEXAMPLES:\nHow many moles in 44 g of CO\u2082? (Mr of CO\u2082 = 44)\nn = 44 \u00f7 44 = 1 mol\n\nHow many moles in 9 g of water? (Mr of H\u2082O = 18)\nn = 9 \u00f7 18 = 0.5 mol\n\nWhat mass of CaCO\u2083 is 0.25 mol? (Mr of CaCO\u2083 = 100)\nmass = 0.25 \u00d7 100 = 25 g\n\nWhat mass of NaOH contains 3.01 \u00d7 10\u00b2\u00b3 molecules? (Mr = 40)\nMoles = 3.01 \u00d7 10\u00b2\u00b3 \u00f7 6.02 \u00d7 10\u00b2\u00b3 = 0.5 mol\nMass = 0.5 \u00d7 40 = 20 g", "heading": "Calculating Moles from Mass"}, {"content": "The Avogadro constant links moles to actual numbers of particles:\n\nNumber of particles = moles \u00d7 Avogadro constant (6.02 \u00d7 10\u00b2\u00b3)\nMoles = number of particles \u00f7 6.02 \u00d7 10\u00b2\u00b3\n\nEXAMPLES:\nHow many molecules in 2 mol of H\u2082O?\n2 \u00d7 6.02 \u00d7 10\u00b2\u00b3 = 1.204 \u00d7 10\u00b2\u2074 molecules.\n\nHow many atoms in 0.1 mol of iron?\n0.1 \u00d7 6.02 \u00d7 10\u00b2\u00b3 = 6.02 \u00d7 10\u00b2\u00b2 atoms.\n\nPERCENTAGE MASS:\nPercentage mass of element in compound:\n% mass = (Ar \u00d7 number of those atoms \u00f7 Mr) \u00d7 100\n\nExample: % mass of oxygen in H\u2082SO\u2084 (Mr = 98):\n% O = (16 \u00d7 4 \u00f7 98) \u00d7 100 = (64 \u00f7 98) \u00d7 100 = 65.3%", "heading": "Moles and Number of Particles"}], "variables": [["n", "Amount in moles", "mol", "mol"], ["m", "Mass", "grams", "g"], ["Mr", "Relative formula mass", "", ""], ["N\u2090", "Avogadro constant", "mol\u207b\u00b9", "6.02 \u00d7 10\u00b2\u00b3"]]};
window.KS4SRC["amounts-in-equations"] = {"common_mistake": "Always use the MOLAR RATIO from the balanced equation when converting between moles of different substances. If 2 mol of A produces 1 mol of B, then 0.4 mol of A produces 0.2 mol of B \u2014 not 0.4 mol of B. The ratio comes from the COEFFICIENTS in the balanced equation.", "equations": ["n = m \u00f7 Mr", "% yield = (actual yield \u00f7 theoretical yield) \u00d7 100", "atom economy = (Mr desired products \u00f7 Mr all products) \u00d7 100"], "fifas": [{"label": "Mass Calculation from Equation", "question": "Calculate the mass of hydrogen produced when 1.2 g of magnesium reacts with excess HCl. Mg + 2HCl \u2192 MgCl\u2082 + H\u2082. Ar: Mg=24, H=1.", "steps": [["F", "n = mass \u00f7 Mr; then use molar ratio; then mass = n \u00d7 Mr"], ["I", "n(Mg) = 1.2 \u00f7 24 = 0.05 mol. Ratio Mg:H\u2082 = 1:1, so n(H\u2082) = 0.05 mol. Mr(H\u2082) = 2"], ["F", "mass(H\u2082) = 0.05 \u00d7 2 = 0.1"], ["A", "0.1 g of hydrogen produced"]]}], "key_note": "Balanced equation coefficients = molar ratios. Method: mass \u2192 moles (\u00f7Mr) \u2192 use ratio \u2192 moles \u2192 mass (\u00d7Mr). % yield = (actual \u00f7 theoretical) \u00d7 100. Atom economy = (Mr desired \u00f7 Mr all products) \u00d7 100. High atom economy = less waste.", "matching": {"instruction": "Match each equation to the correct molar ratio statement.", "pairs": [["2Mg + O\u2082 \u2192 2MgO", "2 mol Mg reacts with 1 mol O\u2082 \u2014 Mg:MgO ratio is 1:1"], ["N\u2082 + 3H\u2082 \u2192 2NH\u2083", "1 mol N\u2082 reacts with 3 mol H\u2082 \u2014 N\u2082:NH\u2083 ratio is 1:2"], ["Mg + 2HCl \u2192 MgCl\u2082 + H\u2082", "1 mol Mg reacts with 2 mol HCl to produce 1 mol MgCl\u2082 and 1 mol H\u2082"], ["CaCO\u2083 \u2192 CaO + CO\u2082", "1 mol CaCO\u2083 produces 1 mol CaO and 1 mol CO\u2082"]], "title": "Molar Ratios from Equations"}, "quiz": {"CH": [{"opts": [["0.4 mol \u2014 ratio H\u2082:NH\u2083 = 3:2, so 0.6 \u00d7 (2/3) = 0.4 mol", true], ["0.6 mol \u2014 same moles as H\u2082 used", false], ["0.9 mol \u2014 multiply 0.6 by the coefficient 3/2", false], ["1.2 mol \u2014 double the H\u2082 moles", false]], "q": "N\u2082 + 3H\u2082 \u2192 2NH\u2083. How many moles of NH\u2083 are produced from 0.6 mol of H\u2082?", "wrong_explanations": {"1": "The molar ratio must be used \u2014 3 mol H\u2082 produces 2 mol NH\u2083, so 0.6 mol H\u2082 produces 0.6 \u00d7 (2/3) = 0.4 mol NH\u2083.", "2": "0.6 \u00d7 (3/2) = 0.9 \u2014 this inverts the ratio. H\u2082:NH\u2083 = 3:2, so NH\u2083 = H\u2082 \u00d7 (2/3).", "3": "Doubling would only apply if the ratio were 1:2 \u2014 but H\u2082:NH\u2083 = 3:2."}}, {"opts": [["80% \u2014 % yield = (20 \u00f7 25) \u00d7 100 = 80%", true], ["125% \u2014 % yield = (25 \u00f7 20) \u00d7 100", false], ["5% \u2014 % yield = (5 \u00f7 25) \u00d7 100 (using the difference)", false], ["20% \u2014 using 20 directly as the percentage", false]], "q": "The theoretical yield of a product is 25 g but only 20 g is obtained. What is the percentage yield?", "wrong_explanations": {"1": "Dividing theoretical \u00f7 actual gives a value over 100% \u2014 meaningless for yield. Always divide ACTUAL \u00f7 THEORETICAL.", "2": "The 5 g difference is the LOST yield, not the yield itself. % yield = actual \u00f7 theoretical \u00d7 100.", "3": "20 is the actual yield in grams \u2014 not the percentage. Must divide by theoretical yield."}}], "TH": [{"opts": [["0.4 mol \u2014 ratio H\u2082:NH\u2083 = 3:2, so 0.6 \u00d7 (2/3) = 0.4 mol", true], ["0.6 mol \u2014 same moles as H\u2082 used", false], ["0.9 mol \u2014 multiply 0.6 by the coefficient 3/2", false], ["1.2 mol \u2014 double the H\u2082 moles", false]], "q": "N\u2082 + 3H\u2082 \u2192 2NH\u2083. How many moles of NH\u2083 are produced from 0.6 mol of H\u2082?", "wrong_explanations": {"1": "The molar ratio must be used \u2014 3 mol H\u2082 produces 2 mol NH\u2083, so 0.6 mol H\u2082 produces 0.6 \u00d7 (2/3) = 0.4 mol NH\u2083.", "2": "0.6 \u00d7 (3/2) = 0.9 \u2014 this inverts the ratio. H\u2082:NH\u2083 = 3:2, so NH\u2083 = H\u2082 \u00d7 (2/3).", "3": "Doubling would only apply if the ratio were 1:2 \u2014 but H\u2082:NH\u2083 = 3:2."}}, {"opts": [["80% \u2014 % yield = (20 \u00f7 25) \u00d7 100 = 80%", true], ["125% \u2014 % yield = (25 \u00f7 20) \u00d7 100", false], ["5% \u2014 % yield = (5 \u00f7 25) \u00d7 100 (using the difference)", false], ["20% \u2014 using 20 directly as the percentage", false]], "q": "The theoretical yield of a product is 25 g but only 20 g is obtained. What is the percentage yield?", "wrong_explanations": {"1": "Dividing theoretical \u00f7 actual gives a value over 100% \u2014 meaningless for yield. Always divide ACTUAL \u00f7 THEORETICAL.", "2": "The 5 g difference is the LOST yield, not the yield itself. % yield = actual \u00f7 theoretical \u00d7 100.", "3": "20 is the actual yield in grams \u2014 not the percentage. Must divide by theoretical yield."}}]}, "summary": "Use balanced equations and moles to calculate masses of reactants and products.", "theory": [{"content": "A BALANCED equation gives the MOLAR RATIO of reactants and products \u2014 the coefficients show the ratio of moles.\n\nExamples:\n2Mg + O\u2082 \u2192 2MgO\nMeans: 2 mol Mg reacts with 1 mol O\u2082 to produce 2 mol MgO.\nMolar ratio Mg : O\u2082 : MgO = 2 : 1 : 2.\n\nMg + 2HCl \u2192 MgCl\u2082 + H\u2082\nMeans: 1 mol Mg reacts with 2 mol HCl to produce 1 mol MgCl\u2082 and 1 mol H\u2082.\n\nN\u2082 + 3H\u2082 \u2192 2NH\u2083\nMeans: 1 mol N\u2082 reacts with 3 mol H\u2082 to produce 2 mol NH\u2083.\n\nKey principle: the molar ratio in the balanced equation is always maintained, whatever the actual quantities used.", "heading": "Molar Ratios from Balanced Equations"}, {"content": "STANDARD METHOD for calculating masses in reactions:\n\nStep 1: Write the balanced equation.\nStep 2: Write the molar ratio from the equation.\nStep 3: Convert given mass to moles: n = mass \u00f7 Mr.\nStep 4: Use the molar ratio to find moles of the unknown substance.\nStep 5: Convert moles back to mass: mass = n \u00d7 Mr.\n\nEXAMPLE:\nHow much magnesium oxide forms when 4.8 g of magnesium burns?\n2Mg + O\u2082 \u2192 2MgO\nStep 1: 2 mol Mg \u2192 2 mol MgO (ratio 1:1)\nStep 2: n(Mg) = 4.8 \u00f7 24 = 0.2 mol\nStep 3: n(MgO) = 0.2 mol (same ratio)\nStep 4: mass(MgO) = 0.2 \u00d7 40 = 8.0 g", "heading": "Calculating Masses Using Moles \u2014 The Method"}, {"content": "THEORETICAL YIELD: the maximum mass of product calculated from the equation.\nACTUAL YIELD: the mass actually obtained in the experiment.\nActual yield is always LESS than or equal to theoretical yield.\n\nWhy actual yield < theoretical yield:\nReaction may not go to completion (reversible reactions).\nSide reactions produce unwanted products.\nProduct lost during transfer/purification.\nReactants may be impure.\n\nPERCENTAGE YIELD:\n% yield = (actual yield \u00f7 theoretical yield) \u00d7 100\n\nEXAMPLE:\nTheoretical yield of MgO = 8.0 g. Actual yield = 7.2 g.\n% yield = (7.2 \u00f7 8.0) \u00d7 100 = 90%\n\nATOM ECONOMY:\nAtom economy = (Mr of desired products \u00f7 Mr of ALL products) \u00d7 100\nHigh atom economy = less waste, more sustainable, more cost-effective.\nAddition reactions have 100% atom economy (one product only).", "heading": "Percentage Yield"}], "variables": [["n", "Amount in moles", "mol", "mol"], ["m", "Mass", "grams", "g"], ["Mr", "Relative formula mass", "", ""]]};
window.KS4SRC["oxidation-reduction"] = {"common_mistake": "In a redox reaction, the REDUCING AGENT is OXIDISED (it gives away electrons/oxygen). The OXIDISING AGENT is REDUCED (it receives electrons/gains oxygen). This is counterintuitive \u2014 an oxidising agent doesn't stay oxidised, it gets reduced. Remember: agents do the opposite of what they're called.", "equations": ["Oxidation = gain of oxygen / loss of electrons", "Reduction = loss of oxygen / gain of electrons", "OIL RIG: Oxidation Is Loss, Reduction Is Gain (electrons)"], "higher": "Define precisely: oxidation = loss of electrons; reduction = gain of electrons (OIL RIG). Write half equations for oxidation and reduction. Identify oxidising agents (gain electrons, are reduced) and reducing agents (lose electrons, are oxidised). Apply to displacement and electrolysis reactions.", "key_note": "Oxidation: gain O / lose electrons. Reduction: lose O / gain electrons. OIL RIG. Always happen together (redox). Reducing agent: donates electrons \u2192 gets oxidised. Oxidising agent: accepts electrons \u2192 gets reduced. Carbon and hydrogen are common reducing agents.", "matching": {"instruction": "Identify whether each substance is oxidised or reduced in the reaction.", "pairs": [["Oxidised", "Mg in Mg + O\u2082 \u2192 MgO \u2014 magnesium gains oxygen"], ["Reduced", "CuO in CuO + H\u2082 \u2192 Cu + H\u2082O \u2014 copper oxide loses oxygen"], ["Oxidised", "H\u2082 in CuO + H\u2082 \u2192 Cu + H\u2082O \u2014 hydrogen gains oxygen"], ["Reduced", "Fe\u2082O\u2083 in Fe\u2082O\u2083 + 3CO \u2192 2Fe + 3CO\u2082 \u2014 iron oxide loses oxygen"], ["Oxidised", "Na in Na \u2192 Na\u207a + e\u207b \u2014 sodium loses an electron (OIL RIG)"]], "title": "Oxidised or Reduced?"}, "quiz": {"CF": [{"opts": [["Hydrogen (H\u2082) \u2014 it reduces the copper oxide by removing its oxygen, and is itself oxidised to water", true], ["Copper oxide \u2014 it causes the hydrogen to become water", false], ["Copper \u2014 it is the product of reduction", false], ["Water \u2014 it is formed when hydrogen is reduced", false]], "q": "In the reaction CuO + H\u2082 \u2192 Cu + H\u2082O, what is the reducing agent?", "wrong_explanations": {"1": "Copper oxide is the OXIDISING AGENT \u2014 it provides the oxygen that oxidises hydrogen. It is itself reduced.", "2": "Copper is the PRODUCT of the reduction of CuO \u2014 it is not a reducing agent.", "3": "Water is a PRODUCT \u2014 reducing agents are reactants that cause reduction of another substance."}}, {"opts": [["Oxidation Is Loss (of electrons), Reduction Is Gain (of electrons)", true], ["Oxidation Involves Losing Reactants, Reduction Involves Gaining", false], ["Oxygen In Liquid, Reactions In Gas", false], ["Only In Liquids Reactions Involve Gases", false]], "q": "What does OIL RIG stand for?", "wrong_explanations": {"1": "OIL RIG specifically refers to ELECTRONS \u2014 Oxidation Is Loss of electrons, Reduction Is Gain of electrons. The words 'reactants' and 'gaining' are incorrect.", "2": "OIL RIG is a memory aid specifically about electron transfer in redox reactions \u2014 not about phases or states of matter.", "3": "OIL RIG is entirely about electrons in redox reactions \u2014 not about the physical state of substances."}}], "CH": [{"opts": [["Hydrogen (H\u2082) \u2014 it reduces the copper oxide by removing its oxygen, and is itself oxidised to water", true], ["Copper oxide \u2014 it causes the hydrogen to become water", false], ["Copper \u2014 it is the product of reduction", false], ["Water \u2014 it is formed when hydrogen is reduced", false]], "q": "In the reaction CuO + H\u2082 \u2192 Cu + H\u2082O, what is the reducing agent?", "wrong_explanations": {"1": "Copper oxide is the OXIDISING AGENT \u2014 it provides the oxygen that oxidises hydrogen. It is itself reduced.", "2": "Copper is the PRODUCT of the reduction of CuO \u2014 it is not a reducing agent.", "3": "Water is a PRODUCT \u2014 reducing agents are reactants that cause reduction of another substance."}}, {"opts": [["Oxidation Is Loss (of electrons), Reduction Is Gain (of electrons)", true], ["Oxidation Involves Losing Reactants, Reduction Involves Gaining", false], ["Oxygen In Liquid, Reactions In Gas", false], ["Only In Liquids Reactions Involve Gases", false]], "q": "What does OIL RIG stand for?", "wrong_explanations": {"1": "OIL RIG specifically refers to ELECTRONS \u2014 Oxidation Is Loss of electrons, Reduction Is Gain of electrons. The words 'reactants' and 'gaining' are incorrect.", "2": "OIL RIG is a memory aid specifically about electron transfer in redox reactions \u2014 not about phases or states of matter.", "3": "OIL RIG is entirely about electrons in redox reactions \u2014 not about the physical state of substances."}}], "TF": [{"opts": [["Hydrogen (H\u2082) \u2014 it reduces the copper oxide by removing its oxygen, and is itself oxidised to water", true], ["Copper oxide \u2014 it causes the hydrogen to become water", false], ["Copper \u2014 it is the product of reduction", false], ["Water \u2014 it is formed when hydrogen is reduced", false]], "q": "In the reaction CuO + H\u2082 \u2192 Cu + H\u2082O, what is the reducing agent?", "wrong_explanations": {"1": "Copper oxide is the OXIDISING AGENT \u2014 it provides the oxygen that oxidises hydrogen. It is itself reduced.", "2": "Copper is the PRODUCT of the reduction of CuO \u2014 it is not a reducing agent.", "3": "Water is a PRODUCT \u2014 reducing agents are reactants that cause reduction of another substance."}}, {"opts": [["Oxidation Is Loss (of electrons), Reduction Is Gain (of electrons)", true], ["Oxidation Involves Losing Reactants, Reduction Involves Gaining", false], ["Oxygen In Liquid, Reactions In Gas", false], ["Only In Liquids Reactions Involve Gases", false]], "q": "What does OIL RIG stand for?", "wrong_explanations": {"1": "OIL RIG specifically refers to ELECTRONS \u2014 Oxidation Is Loss of electrons, Reduction Is Gain of electrons. The words 'reactants' and 'gaining' are incorrect.", "2": "OIL RIG is a memory aid specifically about electron transfer in redox reactions \u2014 not about phases or states of matter.", "3": "OIL RIG is entirely about electrons in redox reactions \u2014 not about the physical state of substances."}}], "TH": [{"opts": [["Hydrogen (H\u2082) \u2014 it reduces the copper oxide by removing its oxygen, and is itself oxidised to water", true], ["Copper oxide \u2014 it causes the hydrogen to become water", false], ["Copper \u2014 it is the product of reduction", false], ["Water \u2014 it is formed when hydrogen is reduced", false]], "q": "In the reaction CuO + H\u2082 \u2192 Cu + H\u2082O, what is the reducing agent?", "wrong_explanations": {"1": "Copper oxide is the OXIDISING AGENT \u2014 it provides the oxygen that oxidises hydrogen. It is itself reduced.", "2": "Copper is the PRODUCT of the reduction of CuO \u2014 it is not a reducing agent.", "3": "Water is a PRODUCT \u2014 reducing agents are reactants that cause reduction of another substance."}}, {"opts": [["Oxidation Is Loss (of electrons), Reduction Is Gain (of electrons)", true], ["Oxidation Involves Losing Reactants, Reduction Involves Gaining", false], ["Oxygen In Liquid, Reactions In Gas", false], ["Only In Liquids Reactions Involve Gases", false]], "q": "What does OIL RIG stand for?", "wrong_explanations": {"1": "OIL RIG specifically refers to ELECTRONS \u2014 Oxidation Is Loss of electrons, Reduction Is Gain of electrons. The words 'reactants' and 'gaining' are incorrect.", "2": "OIL RIG is a memory aid specifically about electron transfer in redox reactions \u2014 not about phases or states of matter.", "3": "OIL RIG is entirely about electrons in redox reactions \u2014 not about the physical state of substances."}}]}, "summary": "Define oxidation and reduction in terms of oxygen gain/loss and use OIL RIG.", "theory": [{"content": "OXIDATION and REDUCTION always occur TOGETHER in the same reaction \u2014 called a REDOX reaction.\n\nIn terms of OXYGEN:\nOXIDATION = GAIN of oxygen.\nREDUCTION = LOSS of oxygen.\n\nExamples:\nMg + O\u2082 \u2192 MgO\nMagnesium is OXIDISED \u2014 it gains oxygen.\n\nCuO + H\u2082 \u2192 Cu + H\u2082O\nCopper oxide is REDUCED \u2014 it loses oxygen.\nHydrogen is OXIDISED \u2014 it gains oxygen.\n\nFe\u2082O\u2083 + 3CO \u2192 2Fe + 3CO\u2082\nIron oxide (Fe\u2082O\u2083) is REDUCED \u2014 iron loses its oxygen.\nCarbon monoxide (CO) is OXIDISED \u2014 it gains oxygen to become CO\u2082.", "heading": "Oxidation and Reduction \u2014 Oxygen Definitions"}, {"content": "At a more advanced level, oxidation and reduction are defined in terms of ELECTRONS:\n\nOIL RIG:\nOxidation Is Loss (of electrons)\nReduction Is Gain (of electrons)\n\nThink of OIL RIG as a memory device \u2014 it only works when you remember what each letter means.\n\nEXAMPLES:\nNa \u2192 Na\u207a + e\u207b \u2014 sodium LOSES an electron \u2192 sodium is OXIDISED.\nCl + e\u207b \u2192 Cl\u207b \u2014 chlorine GAINS an electron \u2192 chlorine is REDUCED.\n\nIn the reaction: Na + Cl \u2192 Na\u207a + Cl\u207b\nSodium is OXIDISED (loses e\u207b). Chlorine is REDUCED (gains e\u207b).\nThis is a REDOX reaction \u2014 both happen simultaneously.\n\nThe substance that causes oxidation is the OXIDISING AGENT.\nThe substance that causes reduction is the REDUCING AGENT.\n\nNote: the oxidising agent is itself REDUCED (it gains electrons). The reducing agent is itself OXIDISED (it loses electrons).", "heading": "OIL RIG \u2014 Electron Definitions (Overview)"}, {"content": "REDUCING AGENT \u2014 causes reduction of another substance by donating electrons (it is itself OXIDISED):\nCarbon in the blast furnace: reduces iron oxide \u2014 carbon is the REDUCING AGENT (it gets oxidised to CO\u2082).\nHydrogen: reduces copper oxide \u2014 hydrogen is the REDUCING AGENT (gets oxidised to H\u2082O).\n\nOXIDISING AGENT \u2014 causes oxidation of another substance by accepting electrons (it is itself REDUCED):\nOxygen: oxidises metals (is itself reduced to O\u00b2\u207b).\nCopper oxide: oxidises hydrogen (is itself reduced to Cu).\n\nCommon reducing agents: hydrogen, carbon, carbon monoxide, more reactive metals.\nCommon oxidising agents: oxygen, chlorine, hydrogen peroxide, potassium manganate(VII).\n\nREDOX in everyday contexts:\nRusting \u2014 iron is OXIDISED by oxygen and water.\nCombustion \u2014 fuels are OXIDISED by oxygen.\nMetabolic respiration \u2014 glucose is OXIDISED.\nPhotosynthesis \u2014 CO\u2082 is REDUCED to glucose.", "heading": "Oxidising and Reducing Agents"}]};
window.KS4SRC["salts-neutralisation"] = {"common_mistake": "When making a salt by adding excess solid to acid \u2014 you MUST use EXCESS solid to ensure ALL the acid reacts. If you don't use excess, some acid remains and the final product will be contaminated with acid. Then filter off the excess unreacted solid \u2014 the salt is in the filtrate.", "equations": ["H\u207a(aq) + OH\u207b(aq) \u2192 H\u2082O(l)  (ionic equation for neutralisation)", "Acid + alkali \u2192 salt + water", "BaCl\u2082(aq) + Na\u2082SO\u2084(aq) \u2192 BaSO\u2084(s) + 2NaCl(aq)"], "key_note": "Soluble salt from acid + solid: add excess solid, filter off excess, evaporate/crystallise. Soluble salt from two soluble reactants: titration to find volumes, then repeat without indicator. Insoluble salt: mix two solutions, precipitate forms, filter/wash/dry. Neutralisation: H\u207a + OH\u207b \u2192 H\u2082O.", "matching": {"instruction": "Match each salt to the best method for making it.", "pairs": [["Copper sulfate (CuSO\u2084)", "Add excess CuO to H\u2082SO\u2084 \u2014 filter off excess CuO \u2014 evaporate to crystallise"], ["Sodium chloride (NaCl)", "Titration \u2014 NaOH + HCl \u2014 find exact volume needed, then evaporate"], ["Barium sulfate (BaSO\u2084)", "Precipitation \u2014 mix BaCl\u2082(aq) + Na\u2082SO\u2084(aq) \u2014 filter and dry"], ["Zinc chloride (ZnCl\u2082)", "Add excess zinc carbonate to HCl \u2014 filter off excess \u2014 evaporate"]], "title": "Method for Making Each Salt"}, "quiz": {"CF": [{"opts": [["To ensure all the acid reacts \u2014 any remaining acid would contaminate the final salt", true], ["To speed up the reaction \u2014 more solid increases the rate", false], ["To increase the yield of salt \u2014 more reactant gives more product", false], ["The excess solid acts as a catalyst", false]], "q": "Why must excess solid be added when making a salt by reacting a metal oxide with an acid?", "wrong_explanations": {"1": "Excess solid does increase the surface area and reaction rate \u2014 but the MAIN reason is to guarantee complete neutralisation of all the acid.", "2": "You cannot add more solid than the acid can react with \u2014 excess produces the same yield. The reason is to ensure complete reaction.", "3": "The excess solid is REMOVED by filtration \u2014 it doesn't catalyse the reaction."}}, {"opts": [["H\u207a(aq) + OH\u207b(aq) \u2192 H\u2082O(l)", true], ["Acid + alkali \u2192 salt + water", false], ["Na\u207a(aq) + Cl\u207b(aq) \u2192 NaCl(s)", false], ["H\u2082 + O\u2082 \u2192 H\u2082O", false]], "q": "What is the ionic equation for neutralisation?", "wrong_explanations": {"1": "This is the WORD equation \u2014 an ionic equation uses symbols and charges. The ionic equation H\u207a + OH\u207b \u2192 H\u2082O shows the actual ions involved.", "2": "This is a precipitation ionic equation \u2014 it describes salt formation, not neutralisation.", "3": "This is the equation for burning hydrogen in oxygen \u2014 not neutralisation."}}], "CH": [{"opts": [["To ensure all the acid reacts \u2014 any remaining acid would contaminate the final salt", true], ["To speed up the reaction \u2014 more solid increases the rate", false], ["To increase the yield of salt \u2014 more reactant gives more product", false], ["The excess solid acts as a catalyst", false]], "q": "Why must excess solid be added when making a salt by reacting a metal oxide with an acid?", "wrong_explanations": {"1": "Excess solid does increase the surface area and reaction rate \u2014 but the MAIN reason is to guarantee complete neutralisation of all the acid.", "2": "You cannot add more solid than the acid can react with \u2014 excess produces the same yield. The reason is to ensure complete reaction.", "3": "The excess solid is REMOVED by filtration \u2014 it doesn't catalyse the reaction."}}, {"opts": [["H\u207a(aq) + OH\u207b(aq) \u2192 H\u2082O(l)", true], ["Acid + alkali \u2192 salt + water", false], ["Na\u207a(aq) + Cl\u207b(aq) \u2192 NaCl(s)", false], ["H\u2082 + O\u2082 \u2192 H\u2082O", false]], "q": "What is the ionic equation for neutralisation?", "wrong_explanations": {"1": "This is the WORD equation \u2014 an ionic equation uses symbols and charges. The ionic equation H\u207a + OH\u207b \u2192 H\u2082O shows the actual ions involved.", "2": "This is a precipitation ionic equation \u2014 it describes salt formation, not neutralisation.", "3": "This is the equation for burning hydrogen in oxygen \u2014 not neutralisation."}}], "TF": [{"opts": [["To ensure all the acid reacts \u2014 any remaining acid would contaminate the final salt", true], ["To speed up the reaction \u2014 more solid increases the rate", false], ["To increase the yield of salt \u2014 more reactant gives more product", false], ["The excess solid acts as a catalyst", false]], "q": "Why must excess solid be added when making a salt by reacting a metal oxide with an acid?", "wrong_explanations": {"1": "Excess solid does increase the surface area and reaction rate \u2014 but the MAIN reason is to guarantee complete neutralisation of all the acid.", "2": "You cannot add more solid than the acid can react with \u2014 excess produces the same yield. The reason is to ensure complete reaction.", "3": "The excess solid is REMOVED by filtration \u2014 it doesn't catalyse the reaction."}}, {"opts": [["H\u207a(aq) + OH\u207b(aq) \u2192 H\u2082O(l)", true], ["Acid + alkali \u2192 salt + water", false], ["Na\u207a(aq) + Cl\u207b(aq) \u2192 NaCl(s)", false], ["H\u2082 + O\u2082 \u2192 H\u2082O", false]], "q": "What is the ionic equation for neutralisation?", "wrong_explanations": {"1": "This is the WORD equation \u2014 an ionic equation uses symbols and charges. The ionic equation H\u207a + OH\u207b \u2192 H\u2082O shows the actual ions involved.", "2": "This is a precipitation ionic equation \u2014 it describes salt formation, not neutralisation.", "3": "This is the equation for burning hydrogen in oxygen \u2014 not neutralisation."}}], "TH": [{"opts": [["To ensure all the acid reacts \u2014 any remaining acid would contaminate the final salt", true], ["To speed up the reaction \u2014 more solid increases the rate", false], ["To increase the yield of salt \u2014 more reactant gives more product", false], ["The excess solid acts as a catalyst", false]], "q": "Why must excess solid be added when making a salt by reacting a metal oxide with an acid?", "wrong_explanations": {"1": "Excess solid does increase the surface area and reaction rate \u2014 but the MAIN reason is to guarantee complete neutralisation of all the acid.", "2": "You cannot add more solid than the acid can react with \u2014 excess produces the same yield. The reason is to ensure complete reaction.", "3": "The excess solid is REMOVED by filtration \u2014 it doesn't catalyse the reaction."}}, {"opts": [["H\u207a(aq) + OH\u207b(aq) \u2192 H\u2082O(l)", true], ["Acid + alkali \u2192 salt + water", false], ["Na\u207a(aq) + Cl\u207b(aq) \u2192 NaCl(s)", false], ["H\u2082 + O\u2082 \u2192 H\u2082O", false]], "q": "What is the ionic equation for neutralisation?", "wrong_explanations": {"1": "This is the WORD equation \u2014 an ionic equation uses symbols and charges. The ionic equation H\u207a + OH\u207b \u2192 H\u2082O shows the actual ions involved.", "2": "This is a precipitation ionic equation \u2014 it describes salt formation, not neutralisation.", "3": "This is the equation for burning hydrogen in oxygen \u2014 not neutralisation."}}]}, "rp": "RP3 (Chemistry) \u2014 Prepare a sample of a pure, dry hydrated copper sulfate salt starting from copper oxide and sulfuric acid using add-excess-solid method.", "summary": "Describe methods for making pure dry salts from acids and how neutralisation works.", "theory": [{"content": "The method for making a salt depends on whether it is SOLUBLE or INSOLUBLE.\n\nMETHOD 1 \u2014 Acid + excess metal/metal oxide/carbonate (for soluble salts):\n1. Add excess solid (metal, metal oxide or carbonate) to the acid \u2014 ensures all acid is used up.\n2. FILTER off the excess unreacted solid (the salt remains in solution).\n3. EVAPORATE the filtrate to crystallise the salt, or leave to crystallise slowly.\n4. Filter and dry the crystals.\n\nExample \u2014 copper sulfate from copper oxide:\nCuO + H\u2082SO\u2084 \u2192 CuSO\u2084 + H\u2082O\nAdd excess black CuO powder to warm sulfuric acid \u2192 blue solution forms.\nFilter \u2192 blue CuSO\u2084 solution passes through.\nEvaporate \u2192 blue CuSO\u2084 crystals form.\n\nMETHOD 2 \u2014 Titration (for soluble salts from soluble starting materials):\nUsed when both reactants are soluble (e.g. NaOH + HCl \u2192 NaCl + H\u2082O).\nCannot use Method 1 \u2014 cannot filter off excess solid.\nInstead, use a TITRATION to find the exact volume of acid needed to neutralise the alkali.\nThen repeat without indicator \u2192 evaporate to get pure salt crystals.", "heading": "Methods of Making Salts"}, {"content": "INSOLUBLE SALTS cannot be made from evaporation \u2014 they would never crystallise from solution.\n\nThey are made by MIXING two solutions that each contain one of the ions needed.\nThe insoluble salt PRECIPITATES immediately.\n\nExample \u2014 making barium sulfate (BaSO\u2084):\nBaCl\u2082(aq) + Na\u2082SO\u2084(aq) \u2192 BaSO\u2084(s) + 2NaCl(aq)\nMix barium chloride solution + sodium sulfate solution.\nBaSO\u2084 precipitates as a white solid immediately.\nFILTER to collect the precipitate.\nWASH with distilled water to remove soluble impurities.\nDRY in an oven.\n\nPrecipitation reactions are also used to:\nRemove unwanted ions from solution (e.g. water treatment).\nTest for specific ions (e.g. adding AgNO\u2083 to test for chloride ions \u2014 white AgCl precipitate forms).", "heading": "Making Insoluble Salts \u2014 Precipitation"}, {"content": "NEUTRALISATION is the reaction between an ACID and a BASE (or alkali) to form a SALT and WATER.\n\nThe IONIC EQUATION for neutralisation is always the same:\nH\u207a(aq) + OH\u207b(aq) \u2192 H\u2082O(l)\n\nThis shows the ESSENTIAL reaction \u2014 a hydrogen ion from the acid combines with a hydroxide ion from the alkali to form water.\n\nTITRATION is the technique for precisely determining how much acid neutralises a given volume of alkali:\n1. Pipette a known volume (e.g. 25.00 cm\u00b3) of alkali into a conical flask.\n2. Add a few drops of INDICATOR (e.g. phenolphthalein \u2014 pink in alkali, colourless in acid).\n3. Slowly add acid from a BURETTE until the indicator just changes colour (the END POINT).\n4. Record the volume of acid used (the TITRE).\n5. Repeat to get concordant (consistent) results.\n6. Calculate mean titre from concordant results.\n\nTo make a PURE SALT by titration:\nRepeat without indicator \u2014 the indicator would contaminate the salt.\nUse the known volume from the titration.", "heading": "Neutralisation in Detail"}]};
window.KS4SRC["ph-scale"] = {"common_mistake": "Lower pH = MORE ACIDIC = MORE H\u207a ions. Higher pH = MORE ALKALINE = FEWER H\u207a ions (more OH\u207b). Students often confuse pH 2 and pH 12 \u2014 pH 2 is strongly acidic, pH 12 is strongly alkaline. pH 7 is neutral \u2014 pure water. NOT all solutions at pH 7 are water.", "higher": "Strong acids fully dissociate (HCl \u2192 H\u207a + Cl\u207b) \u2014 maximum H\u207a at given concentration. Weak acids partially dissociate (CH\u2083COOH \u21cc CH\u2083COO\u207b + H\u207a) \u2014 less H\u207a at same concentration \u2192 higher pH. Strong acid and weak acid at same concentration: strong acid has lower pH. Strong \u2260 concentrated.", "key_note": "pH 0\u20136: acidic. pH 7: neutral. pH 8\u201314: alkaline. Lower pH = more H\u207a ions. pH scale is logarithmic \u2014 each unit = 10\u00d7 change in H\u207a. Universal indicator: shows range of colours. Phenolphthalein: colourless in acid, pink in alkali. pH meter: most accurate.", "matching": {"instruction": "Match each pH value to the correct description.", "pairs": [["pH 1", "Strongly acidic \u2014 high concentration of H\u207a ions"], ["pH 7", "Neutral \u2014 equal H\u207a and OH\u207b ions \u2014 pure water at 25\u00b0C"], ["pH 13", "Strongly alkaline \u2014 high concentration of OH\u207b ions"], ["pH 4", "Weakly acidic \u2014 e.g. black coffee or tomato juice"], ["pH 10", "Weakly alkaline \u2014 e.g. baking soda solution"]], "title": "Match the pH to the Description"}, "quiz": {"CF": [{"opts": [["pH 2 has 100 times more H\u207a than pH 4 \u2014 each unit on the log scale is 10\u00d7", true], ["pH 2 has twice as many H\u207a ions as pH 4", false], ["pH 4 has more H\u207a ions \u2014 higher pH means more hydrogen", false], ["They have the same H\u207a concentration \u2014 both are acidic", false]], "q": "A solution has a pH of 2. Another has a pH of 4. How do their H\u207a ion concentrations compare?", "wrong_explanations": {"1": "The pH scale is LOGARITHMIC \u2014 each unit represents a 10\u00d7 change, not a 2\u00d7 change. pH 2 vs pH 4 = 10\u00b2 = 100\u00d7 difference.", "2": "LOWER pH means MORE H\u207a ions \u2014 pH 2 is more acidic than pH 4, not less.", "3": "Both are acidic (below 7) but have very different H\u207a concentrations \u2014 pH 2 is much more acidic."}}, {"opts": [["The pH increases towards 7 \u2014 dilution reduces H\u207a concentration, making it less acidic", true], ["The pH decreases \u2014 water is neutral so it makes the acid stronger", false], ["The pH stays the same \u2014 water doesn't affect the acid", false], ["The pH jumps immediately to 7 \u2014 water always neutralises acids", false]], "q": "An acid is diluted by adding water. What happens to its pH?", "wrong_explanations": {"1": "Water does not make acid stronger \u2014 adding water DILUTES the acid, reducing H\u207a concentration and raising pH.", "2": "Water does affect the acid \u2014 it reduces the concentration of H\u207a ions (dilutes them). The pH INCREASES.", "3": "Unless you add enormous amounts of water, the pH approaches 7 gradually but never quite reaches it \u2014 you are diluting, not neutralising."}}], "CH": [{"opts": [["pH 2 has 100 times more H\u207a than pH 4 \u2014 each unit on the log scale is 10\u00d7", true], ["pH 2 has twice as many H\u207a ions as pH 4", false], ["pH 4 has more H\u207a ions \u2014 higher pH means more hydrogen", false], ["They have the same H\u207a concentration \u2014 both are acidic", false]], "q": "A solution has a pH of 2. Another has a pH of 4. How do their H\u207a ion concentrations compare?", "wrong_explanations": {"1": "The pH scale is LOGARITHMIC \u2014 each unit represents a 10\u00d7 change, not a 2\u00d7 change. pH 2 vs pH 4 = 10\u00b2 = 100\u00d7 difference.", "2": "LOWER pH means MORE H\u207a ions \u2014 pH 2 is more acidic than pH 4, not less.", "3": "Both are acidic (below 7) but have very different H\u207a concentrations \u2014 pH 2 is much more acidic."}}, {"opts": [["The pH increases towards 7 \u2014 dilution reduces H\u207a concentration, making it less acidic", true], ["The pH decreases \u2014 water is neutral so it makes the acid stronger", false], ["The pH stays the same \u2014 water doesn't affect the acid", false], ["The pH jumps immediately to 7 \u2014 water always neutralises acids", false]], "q": "An acid is diluted by adding water. What happens to its pH?", "wrong_explanations": {"1": "Water does not make acid stronger \u2014 adding water DILUTES the acid, reducing H\u207a concentration and raising pH.", "2": "Water does affect the acid \u2014 it reduces the concentration of H\u207a ions (dilutes them). The pH INCREASES.", "3": "Unless you add enormous amounts of water, the pH approaches 7 gradually but never quite reaches it \u2014 you are diluting, not neutralising."}}], "TF": [{"opts": [["pH 2 has 100 times more H\u207a than pH 4 \u2014 each unit on the log scale is 10\u00d7", true], ["pH 2 has twice as many H\u207a ions as pH 4", false], ["pH 4 has more H\u207a ions \u2014 higher pH means more hydrogen", false], ["They have the same H\u207a concentration \u2014 both are acidic", false]], "q": "A solution has a pH of 2. Another has a pH of 4. How do their H\u207a ion concentrations compare?", "wrong_explanations": {"1": "The pH scale is LOGARITHMIC \u2014 each unit represents a 10\u00d7 change, not a 2\u00d7 change. pH 2 vs pH 4 = 10\u00b2 = 100\u00d7 difference.", "2": "LOWER pH means MORE H\u207a ions \u2014 pH 2 is more acidic than pH 4, not less.", "3": "Both are acidic (below 7) but have very different H\u207a concentrations \u2014 pH 2 is much more acidic."}}, {"opts": [["The pH increases towards 7 \u2014 dilution reduces H\u207a concentration, making it less acidic", true], ["The pH decreases \u2014 water is neutral so it makes the acid stronger", false], ["The pH stays the same \u2014 water doesn't affect the acid", false], ["The pH jumps immediately to 7 \u2014 water always neutralises acids", false]], "q": "An acid is diluted by adding water. What happens to its pH?", "wrong_explanations": {"1": "Water does not make acid stronger \u2014 adding water DILUTES the acid, reducing H\u207a concentration and raising pH.", "2": "Water does affect the acid \u2014 it reduces the concentration of H\u207a ions (dilutes them). The pH INCREASES.", "3": "Unless you add enormous amounts of water, the pH approaches 7 gradually but never quite reaches it \u2014 you are diluting, not neutralising."}}], "TH": [{"opts": [["pH 2 has 100 times more H\u207a than pH 4 \u2014 each unit on the log scale is 10\u00d7", true], ["pH 2 has twice as many H\u207a ions as pH 4", false], ["pH 4 has more H\u207a ions \u2014 higher pH means more hydrogen", false], ["They have the same H\u207a concentration \u2014 both are acidic", false]], "q": "A solution has a pH of 2. Another has a pH of 4. How do their H\u207a ion concentrations compare?", "wrong_explanations": {"1": "The pH scale is LOGARITHMIC \u2014 each unit represents a 10\u00d7 change, not a 2\u00d7 change. pH 2 vs pH 4 = 10\u00b2 = 100\u00d7 difference.", "2": "LOWER pH means MORE H\u207a ions \u2014 pH 2 is more acidic than pH 4, not less.", "3": "Both are acidic (below 7) but have very different H\u207a concentrations \u2014 pH 2 is much more acidic."}}, {"opts": [["The pH increases towards 7 \u2014 dilution reduces H\u207a concentration, making it less acidic", true], ["The pH decreases \u2014 water is neutral so it makes the acid stronger", false], ["The pH stays the same \u2014 water doesn't affect the acid", false], ["The pH jumps immediately to 7 \u2014 water always neutralises acids", false]], "q": "An acid is diluted by adding water. What happens to its pH?", "wrong_explanations": {"1": "Water does not make acid stronger \u2014 adding water DILUTES the acid, reducing H\u207a concentration and raising pH.", "2": "Water does affect the acid \u2014 it reduces the concentration of H\u207a ions (dilutes them). The pH INCREASES.", "3": "Unless you add enormous amounts of water, the pH approaches 7 gradually but never quite reaches it \u2014 you are diluting, not neutralising."}}]}, "summary": "Describe the pH scale, what it measures and how indicators are used.", "theory": [{"content": "The pH SCALE measures the CONCENTRATION of hydrogen ions (H\u207a) in a solution \u2014 it indicates how acidic or alkaline a solution is.\n\nScale range: 0 to 14 (though values slightly outside this range are possible).\n\npH 0\u20136: ACIDIC (more H\u207a ions than OH\u207b ions)\npH 7: NEUTRAL (equal H\u207a and OH\u207b \u2014 pure water at 25\u00b0C)\npH 8\u201314: ALKALINE (more OH\u207b ions than H\u207a ions)\n\nThe pH scale is LOGARITHMIC \u2014 each unit change represents a 10\u00d7 change in H\u207a concentration:\npH 3 has 10\u00d7 more H\u207a than pH 4.\npH 3 has 100\u00d7 more H\u207a than pH 5.\n\nTypical pH values:\nHydrochloric acid (conc.): pH ~0\u20131\nVinegar (ethanoic acid): pH ~3\nCoffee: pH ~5\nPure water: pH 7\nBaking soda solution: pH ~9\nSodium hydroxide solution: pH ~13\u201314", "heading": "The pH Scale"}, {"content": "An INDICATOR is a substance that changes colour depending on the pH of a solution.\n\nUNIVERSAL INDICATOR:\nA mixture of indicators that shows a range of colours across the pH scale.\nRed \u2192 orange \u2192 yellow \u2192 green \u2192 blue \u2192 purple as pH increases from 0 to 14.\nGives an APPROXIMATE pH \u2014 tells you the pH range.\n\nLITMUS:\nRed in ACID, blue in ALKALI, purple in neutral.\nSimple test \u2014 tells you acid or alkali, not the pH number.\n\nPHENOLPHTHALEIN:\nColourless in acid, PINK in alkali.\nUsed in titrations \u2014 clear colour change at the end point.\n\npH PROBE / METER:\nGives a PRECISE numerical pH reading \u2014 more accurate than indicators.\nUsed in industry and for accurate laboratory measurements.\n\nTHE RELATIONSHIP BETWEEN pH AND CONCENTRATION:\nThe MORE H\u207a ions in solution \u2192 LOWER pH (more acidic).\nThe MORE OH\u207b ions in solution \u2192 HIGHER pH (more alkaline).\nAdding water DILUTES the solution \u2192 concentration of H\u207a decreases \u2192 pH INCREASES towards 7.", "heading": "Indicators and Measuring pH"}, {"content": "Adding a BASE to an ACID gradually increases the pH (makes it less acidic).\nAdding an ACID to an ALKALI gradually decreases the pH (makes it less alkaline).\n\nA TITRATION CURVE shows how pH changes as acid is added to alkali:\nAt the START: pH high (~13) \u2014 the solution is strongly alkaline.\nAs acid is added: pH falls slowly at first.\nNear the END POINT: pH drops RAPIDLY \u2014 a large pH change for a small addition.\nAt the END POINT: pH = 7 (if strong acid + strong alkali).\nAfter the end point: pH continues to fall as excess acid is added.\n\nWHY SUCH A SHARP CHANGE NEAR THE END POINT:\nNear the equivalence point, there is very little OH\u207b left to absorb the H\u207a from the added acid.\nSo each small addition of acid produces a large change in H\u207a concentration \u2192 large pH change.", "heading": "Effect of Neutralisation on pH"}]};
window.KS4SRC["strong-weak-acids"] = {"common_mistake": "Strong acid \u2260 concentrated acid. A STRONG acid is fully ionised (complete dissociation). A CONCENTRATED acid has a high number of moles per dm\u00b3. You can have a dilute strong acid (e.g. 0.001 mol/dm\u00b3 HCl) or a concentrated weak acid (e.g. 5 mol/dm\u00b3 CH\u2083COOH). These are independent concepts.", "equations": ["HCl \u2192 H\u207a + Cl\u207b  (strong acid \u2014 complete dissociation)", "CH\u2083COOH \u21cc CH\u2083COO\u207b + H\u207a  (weak acid \u2014 partial dissociation)"], "key_note": "Strong acids: fully ionise (HCl, H\u2082SO\u2084, HNO\u2083). Weak acids: partially ionise (CH\u2083COOH, HF, citric acid). Same concentration \u2192 strong acid has lower pH (more H\u207a). Same pH \u2192 weak acid is at higher concentration. Strong \u2260 concentrated. Weak acid: equilibrium \u2014 \u21cc arrow.", "matching": {"instruction": "Sort each acid into strong (fully ionised) or weak (partially ionised).", "pairs": [["Strong acid", "Hydrochloric acid (HCl) \u2014 HCl \u2192 H\u207a + Cl\u207b \u2014 complete dissociation"], ["Strong acid", "Nitric acid (HNO\u2083) \u2014 HNO\u2083 \u2192 H\u207a + NO\u2083\u207b \u2014 fully ionised"], ["Weak acid", "Ethanoic acid (CH\u2083COOH) \u2014 only ~1% ionised in solution"], ["Weak acid", "Carbonic acid (H\u2082CO\u2083) \u2014 partial ionisation in fizzy drinks"], ["Strong acid", "Sulfuric acid (H\u2082SO\u2084) \u2014 fully ionises to give 2H\u207a per molecule"]], "title": "Strong or Weak Acid?"}, "quiz": {"CH": [{"opts": [["HCl \u2014 it fully ionises, producing [H\u207a] \u2248 0.1 mol/dm\u00b3. CH\u2083COOH only partially ionises, producing far less H\u207a.", true], ["CH\u2083COOH \u2014 weak acids are more reactive and produce more H\u207a", false], ["Both have the same pH \u2014 they are the same concentration", false], ["HCl \u2014 HCl molecules are larger and release more H\u207a per molecule", false]], "q": "Two acids, 0.1 mol/dm\u00b3 HCl and 0.1 mol/dm\u00b3 CH\u2083COOH, are compared. Which has a lower pH and why?", "wrong_explanations": {"1": "Weak acids are LESS reactive per unit concentration \u2014 they produce FEWER H\u207a ions, not more.", "2": "Same concentration does NOT mean same pH \u2014 the degree of ionisation determines [H\u207a], which determines pH.", "3": "HCl produces one H\u207a per molecule (monoprotic) \u2014 the lower pH is due to COMPLETE ionisation, not molecule size."}}, {"opts": [["Yes \u2014 strong means fully ionised, dilute means low concentration. A 0.001 mol/dm\u00b3 HCl solution is dilute but still a strong acid.", true], ["No \u2014 strong acids must always be concentrated", false], ["No \u2014 diluting an acid makes it weak", false], ["Yes \u2014 but only if a catalyst is added to maintain ionisation", false]], "q": "Is it possible to have a dilute solution of a strong acid?", "wrong_explanations": {"1": "Strong/weak describes degree of IONISATION. Concentrated/dilute describes AMOUNT per volume. These are completely independent.", "2": "Diluting HCl just reduces the concentration \u2014 HCl always fully ionises. It doesn't become a weak acid.", "3": "No catalyst is needed \u2014 strength (ionisation) is an intrinsic property of the acid."}}], "TH": [{"opts": [["HCl \u2014 it fully ionises, producing [H\u207a] \u2248 0.1 mol/dm\u00b3. CH\u2083COOH only partially ionises, producing far less H\u207a.", true], ["CH\u2083COOH \u2014 weak acids are more reactive and produce more H\u207a", false], ["Both have the same pH \u2014 they are the same concentration", false], ["HCl \u2014 HCl molecules are larger and release more H\u207a per molecule", false]], "q": "Two acids, 0.1 mol/dm\u00b3 HCl and 0.1 mol/dm\u00b3 CH\u2083COOH, are compared. Which has a lower pH and why?", "wrong_explanations": {"1": "Weak acids are LESS reactive per unit concentration \u2014 they produce FEWER H\u207a ions, not more.", "2": "Same concentration does NOT mean same pH \u2014 the degree of ionisation determines [H\u207a], which determines pH.", "3": "HCl produces one H\u207a per molecule (monoprotic) \u2014 the lower pH is due to COMPLETE ionisation, not molecule size."}}, {"opts": [["Yes \u2014 strong means fully ionised, dilute means low concentration. A 0.001 mol/dm\u00b3 HCl solution is dilute but still a strong acid.", true], ["No \u2014 strong acids must always be concentrated", false], ["No \u2014 diluting an acid makes it weak", false], ["Yes \u2014 but only if a catalyst is added to maintain ionisation", false]], "q": "Is it possible to have a dilute solution of a strong acid?", "wrong_explanations": {"1": "Strong/weak describes degree of IONISATION. Concentrated/dilute describes AMOUNT per volume. These are completely independent.", "2": "Diluting HCl just reduces the concentration \u2014 HCl always fully ionises. It doesn't become a weak acid.", "3": "No catalyst is needed \u2014 strength (ionisation) is an intrinsic property of the acid."}}]}, "summary": "Distinguish between strong and weak acids in terms of ionisation and explain the difference in pH.", "theory": [{"content": "All acids produce H\u207a ions when dissolved in water \u2014 but they differ in how COMPLETELY they ionise.\n\nSTRONG ACIDS \u2014 FULLY ionise in water (\u2192 one-way arrow):\nAll of the acid molecules dissociate into H\u207a and the conjugate base.\nHCl \u2192 H\u207a + Cl\u207b (complete dissociation)\nH\u2082SO\u2084 \u2192 2H\u207a + SO\u2084\u00b2\u207b\nHNO\u2083 \u2192 H\u207a + NO\u2083\u207b\n\nAt a given concentration, a strong acid has the MAXIMUM possible H\u207a concentration.\n\nWEAK ACIDS \u2014 PARTIALLY ionise (\u21cc reversible arrow):\nOnly a small fraction of acid molecules dissociate \u2014 the rest remain as molecules.\nCH\u2083COOH \u21cc CH\u2083COO\u207b + H\u207a (ethanoic acid \u2014 only ~1% ionised)\nH\u2082CO\u2083 \u21cc H\u207a + HCO\u2083\u207b (carbonic acid)\nHF \u21cc H\u207a + F\u207b (hydrofluoric acid)\nCitric acid, lactic acid \u2014 weak acids found in foods.", "heading": "Strong vs Weak Acids \u2014 Degree of Ionisation"}, {"content": "At the SAME CONCENTRATION:\nA strong acid has a LOWER pH than a weak acid.\nBecause: the strong acid provides far more H\u207a ions per dm\u00b3.\n\nEXAMPLE:\n0.1 mol/dm\u00b3 HCl (strong): nearly all molecules ionise \u2192 [H\u207a] \u2248 0.1 mol/dm\u00b3 \u2192 pH \u2248 1.\n0.1 mol/dm\u00b3 CH\u2083COOH (weak): ~1% ionised \u2192 [H\u207a] \u2248 0.001 mol/dm\u00b3 \u2192 pH \u2248 3.\n\nBoth have the SAME CONCENTRATION but very different pH values.\n\nEFFECT OF DILUTION on weak acids:\nAdding water \u2192 equilibrium shifts RIGHT (more ionisation) \u2192 slightly more H\u207a.\nWeak acids become relatively more ionised on dilution.\n\nCOMPARING SAME pH:\nA weak acid at pH 3 contains MORE acid molecules than a strong acid at pH 3.\nThe weak acid solution is at HIGHER CONCENTRATION to achieve the same pH.", "heading": "pH Difference Between Strong and Weak Acids"}, {"content": "At the SAME CONCENTRATION \u2014 a strong acid reacts MORE VIGOROUSLY than a weak acid because it has a higher [H\u207a].\n\nWith magnesium:\n0.1 mol/dm\u00b3 HCl: vigorous fizzing (high [H\u207a]).\n0.1 mol/dm\u00b3 CH\u2083COOH: gentle fizzing (low [H\u207a] \u2014 only partly ionised).\n\nBut: if EXCESS acid is used, both eventually produce the SAME amount of H\u2082.\nWhy: both have the same TOTAL number of acid molecules \u2014 weak acid eventually fully reacts.\n\nWith sodium carbonate:\nStrong acid: effervescence faster.\nWeak acid: effervescence slower \u2014 same total CO\u2082 ultimately produced.\n\nConductivity comparison:\nStrong acid: better electrical conductor (more ions in solution).\nWeak acid: poorer conductor (fewer ions in solution at same concentration).", "heading": "Comparing Reactions of Strong and Weak Acids"}]};
window.KS4SRC["electrolysis-principles"] = {"common_mistake": "CATHODE is NEGATIVE \u2014 positive ions are attracted to it and gain electrons (reduced). ANODE is POSITIVE \u2014 negative ions are attracted to it and lose electrons (oxidised). Students often confuse these. Remember: AN OX (Anode Oxidation) and RED CAT (Reduction at Cathode).", "higher": "Write ionic half equations for all electrode reactions. Explain using OIL RIG: anode = oxidation (OA), cathode = reduction (RC). Remember AN OX, RED CAT. Understand that current is carried by ions in solution and by electrons in external circuit.", "key_note": "Electrolysis: decomposition using electrical energy. Electrolyte: ionic compound that is molten or in solution. Cathode (\u2212): cations attracted, gain electrons, REDUCED. Anode (+): anions attracted, lose electrons, OXIDISED. AN OX, RED CAT. Inert electrodes: graphite or platinum.", "matching": {"instruction": "Match each term to its correct definition.", "pairs": [["Cathode", "Negative electrode \u2014 positive ions attracted here \u2014 reduction occurs"], ["Anode", "Positive electrode \u2014 negative ions attracted here \u2014 oxidation occurs"], ["Electrolyte", "Ionic compound that is molten or dissolved \u2014 conducts electricity and is decomposed"], ["Reduction (at cathode)", "Cations gain electrons \u2014 metal deposited or H\u2082 gas produced"], ["Oxidation (at anode)", "Anions lose electrons \u2014 non-metal gas produced (O\u2082, Cl\u2082)"]], "title": "Electrolysis Key Terms"}, "quiz": {"CF": [{"opts": [["In the solid, ions are fixed in the lattice \u2014 they cannot move to carry charge. Molten NaCl has free-moving ions.", true], ["Solid NaCl doesn't contain ions \u2014 they only form when the compound melts.", false], ["Solid NaCl is too hard for electricity to pass through.", false], ["Electrolysis only works on liquids \u2014 all solids resist decomposition.", false]], "q": "Why can solid sodium chloride not be electrolysed, but molten sodium chloride can?", "wrong_explanations": {"1": "NaCl is always ionic \u2014 Na\u207a and Cl\u207b ions exist in both solid and molten states. The issue is whether they can MOVE.", "2": "Hardness affects mechanical properties, not ionic conductivity \u2014 the issue is ion mobility, not physical hardness.", "3": "Some solids are electrolysed \u2014 e.g. electrolysis of a metal anode in electroplating. The issue specifically with NaCl solid is fixed ions."}}, {"opts": [["At the anode \u2014 negative ions lose electrons here (OIL: Oxidation Is Loss)", true], ["At the cathode \u2014 positive ions gain electrons here", false], ["In the electrolyte \u2014 ions are oxidised as they move through the solution", false], ["At both electrodes simultaneously", false]], "q": "During electrolysis, where does oxidation take place?", "wrong_explanations": {"1": "The CATHODE is where REDUCTION occurs (positive ions GAIN electrons). Remember: RED CAT (Reduction at Cathode).", "2": "Ions move through the solution but are not oxidised or reduced until they reach an electrode.", "3": "Oxidation (at anode) and reduction (at cathode) occur at DIFFERENT electrodes \u2014 at the same time, but not at the same place."}}], "CH": [{"opts": [["In the solid, ions are fixed in the lattice \u2014 they cannot move to carry charge. Molten NaCl has free-moving ions.", true], ["Solid NaCl doesn't contain ions \u2014 they only form when the compound melts.", false], ["Solid NaCl is too hard for electricity to pass through.", false], ["Electrolysis only works on liquids \u2014 all solids resist decomposition.", false]], "q": "Why can solid sodium chloride not be electrolysed, but molten sodium chloride can?", "wrong_explanations": {"1": "NaCl is always ionic \u2014 Na\u207a and Cl\u207b ions exist in both solid and molten states. The issue is whether they can MOVE.", "2": "Hardness affects mechanical properties, not ionic conductivity \u2014 the issue is ion mobility, not physical hardness.", "3": "Some solids are electrolysed \u2014 e.g. electrolysis of a metal anode in electroplating. The issue specifically with NaCl solid is fixed ions."}}, {"opts": [["At the anode \u2014 negative ions lose electrons here (OIL: Oxidation Is Loss)", true], ["At the cathode \u2014 positive ions gain electrons here", false], ["In the electrolyte \u2014 ions are oxidised as they move through the solution", false], ["At both electrodes simultaneously", false]], "q": "During electrolysis, where does oxidation take place?", "wrong_explanations": {"1": "The CATHODE is where REDUCTION occurs (positive ions GAIN electrons). Remember: RED CAT (Reduction at Cathode).", "2": "Ions move through the solution but are not oxidised or reduced until they reach an electrode.", "3": "Oxidation (at anode) and reduction (at cathode) occur at DIFFERENT electrodes \u2014 at the same time, but not at the same place."}}], "TF": [{"opts": [["In the solid, ions are fixed in the lattice \u2014 they cannot move to carry charge. Molten NaCl has free-moving ions.", true], ["Solid NaCl doesn't contain ions \u2014 they only form when the compound melts.", false], ["Solid NaCl is too hard for electricity to pass through.", false], ["Electrolysis only works on liquids \u2014 all solids resist decomposition.", false]], "q": "Why can solid sodium chloride not be electrolysed, but molten sodium chloride can?", "wrong_explanations": {"1": "NaCl is always ionic \u2014 Na\u207a and Cl\u207b ions exist in both solid and molten states. The issue is whether they can MOVE.", "2": "Hardness affects mechanical properties, not ionic conductivity \u2014 the issue is ion mobility, not physical hardness.", "3": "Some solids are electrolysed \u2014 e.g. electrolysis of a metal anode in electroplating. The issue specifically with NaCl solid is fixed ions."}}, {"opts": [["At the anode \u2014 negative ions lose electrons here (OIL: Oxidation Is Loss)", true], ["At the cathode \u2014 positive ions gain electrons here", false], ["In the electrolyte \u2014 ions are oxidised as they move through the solution", false], ["At both electrodes simultaneously", false]], "q": "During electrolysis, where does oxidation take place?", "wrong_explanations": {"1": "The CATHODE is where REDUCTION occurs (positive ions GAIN electrons). Remember: RED CAT (Reduction at Cathode).", "2": "Ions move through the solution but are not oxidised or reduced until they reach an electrode.", "3": "Oxidation (at anode) and reduction (at cathode) occur at DIFFERENT electrodes \u2014 at the same time, but not at the same place."}}], "TH": [{"opts": [["In the solid, ions are fixed in the lattice \u2014 they cannot move to carry charge. Molten NaCl has free-moving ions.", true], ["Solid NaCl doesn't contain ions \u2014 they only form when the compound melts.", false], ["Solid NaCl is too hard for electricity to pass through.", false], ["Electrolysis only works on liquids \u2014 all solids resist decomposition.", false]], "q": "Why can solid sodium chloride not be electrolysed, but molten sodium chloride can?", "wrong_explanations": {"1": "NaCl is always ionic \u2014 Na\u207a and Cl\u207b ions exist in both solid and molten states. The issue is whether they can MOVE.", "2": "Hardness affects mechanical properties, not ionic conductivity \u2014 the issue is ion mobility, not physical hardness.", "3": "Some solids are electrolysed \u2014 e.g. electrolysis of a metal anode in electroplating. The issue specifically with NaCl solid is fixed ions."}}, {"opts": [["At the anode \u2014 negative ions lose electrons here (OIL: Oxidation Is Loss)", true], ["At the cathode \u2014 positive ions gain electrons here", false], ["In the electrolyte \u2014 ions are oxidised as they move through the solution", false], ["At both electrodes simultaneously", false]], "q": "During electrolysis, where does oxidation take place?", "wrong_explanations": {"1": "The CATHODE is where REDUCTION occurs (positive ions GAIN electrons). Remember: RED CAT (Reduction at Cathode).", "2": "Ions move through the solution but are not oxidised or reduced until they reach an electrode.", "3": "Oxidation (at anode) and reduction (at cathode) occur at DIFFERENT electrodes \u2014 at the same time, but not at the same place."}}]}, "summary": "Describe what electrolysis is, how it works and the key terms used.", "theory": [{"content": "ELECTROLYSIS is the decomposition of a substance using ELECTRICAL ENERGY.\n\nFor electrolysis to occur, the substance must be an ELECTROLYTE \u2014 a substance that can conduct electricity AND be decomposed by it.\n\nElectrolytes are ionic compounds that are either:\nMOLTEN (melted) \u2014 ions are free to move through the liquid.\nDISSOLVED in water (aqueous solution) \u2014 ions are free to move through the solution.\n\nSolid ionic compounds CANNOT be electrolysed \u2014 their ions are fixed in the lattice.\n\nElectrolysis is used to:\nExtract reactive metals from their ores (aluminium, sodium).\nElectroplate metals (coating objects with a metal layer).\nPurify metals (e.g. copper refining).\nManufacture chemicals (e.g. chlorine and sodium hydroxide from brine).", "heading": "What is Electrolysis?"}, {"content": "ELECTRODES: the conductors that dip into the electrolyte.\nConnected to a DIRECT CURRENT (DC) power supply.\n\nCATHODE: the NEGATIVE electrode (connected to the negative terminal).\nANODE: the POSITIVE electrode (connected to the positive terminal).\nMemory: CATHode = CATs are negative (they scratch!) or: An-ODE is pOsitivE.\n\nHow it works:\nPositive ions (CATIONS) move TOWARDS the negative cathode.\nAt the cathode: cations GAIN electrons \u2192 REDUCED \u2192 solid metal or hydrogen gas deposited.\n\nNegative ions (ANIONS) move TOWARDS the positive anode.\nAt the anode: anions LOSE electrons \u2192 OXIDISED \u2192 gas or element released.\n\nOVERALL:\nOxidation at the Anode (OA).\nReduction at the Cathode (RC).\nMemory: AN OX, A RED CAT (ANode OXidation; REDuction at CAThode).", "heading": "Key Terms and the Apparatus"}, {"content": "INERT ELECTRODES (e.g. graphite or platinum):\nDo not react with the electrolyte or products.\nSimply provide a surface for ions to discharge.\nGraphite is most commonly used \u2014 cheap and conducts electricity.\n\nREACTIVE ELECTRODES (e.g. copper in electroplating):\nThe anode dissolves into the solution as copper ions.\nThe cathode grows as copper deposits onto it.\nUsed in electroplating and copper purification.\n\nWHY INERT ELECTRODES ARE IMPORTANT:\nIf the anode reacted with the products or electrolyte, it would change the composition of the solution.\nUsing inert electrodes (graphite or platinum) gives consistent, predictable products.\n\nNB \u2014 In aluminium extraction, the CARBON ANODES slowly BURN in the oxygen produced and must be regularly replaced. This is one reason aluminium extraction is expensive.", "heading": "Electrodes \u2014 Inert vs Reactive"}]};
window.KS4SRC["electrolysis-molten"] = {"common_mistake": "In molten ionic compounds, the METAL is always produced at the CATHODE (the negative electrode). This is reduction \u2014 metal ions GAIN electrons. The NON-METAL is always produced at the ANODE (positive electrode). This is oxidation \u2014 non-metal ions LOSE electrons.", "equations": ["2NaCl(l) \u2192 2Na(l) + Cl\u2082(g)  (electrolysis of molten NaCl)", "PbBr\u2082(l) \u2192 Pb(l) + Br\u2082(g)  (electrolysis of molten lead bromide)", "Cathode: Na\u207a + e\u207b \u2192 Na", "Anode: 2Cl\u207b \u2192 Cl\u2082 + 2e\u207b"], "higher": "Write balanced half equations for cathode and anode. Combine to give overall equation. Explain product prediction from ion identity. Justify why reactive metals above carbon cannot be extracted by carbon reduction \u2014 electrolysis of molten compound is the only option.", "key_note": "Molten ionic compound \u2192 only those ions present. Cathode: metal ion + electrons \u2192 metal. Anode: non-metal ions lose electrons \u2192 non-metal (gas or liquid). Molten NaCl \u2192 Na metal + Cl\u2082 gas. Molten PbBr\u2082 \u2192 Pb metal + Br\u2082. Solid won't conduct \u2014 ions must be mobile.", "matching": {"instruction": "Match each electrode product to the correct electrolysis of a molten compound.", "pairs": [["Cathode \u2014 molten NaCl", "Sodium metal (liquid) \u2014 Na\u207a ions gain electrons"], ["Anode \u2014 molten NaCl", "Chlorine gas (yellow-green) \u2014 Cl\u207b ions lose electrons"], ["Cathode \u2014 molten PbBr\u2082", "Lead metal (liquid) \u2014 Pb\u00b2\u207a ions gain 2 electrons each"], ["Anode \u2014 molten PbBr\u2082", "Bromine liquid/vapour (brown) \u2014 Br\u207b ions lose electrons"]], "title": "Products at Each Electrode"}, "quiz": {"CF": [{"opts": [["Calcium metal \u2014 Ca\u00b2\u207a ions are reduced at the negative cathode", true], ["Chlorine gas \u2014 Cl\u207b ions are discharged at the cathode", false], ["Calcium chloride \u2014 no decomposition occurs at the cathode", false], ["Calcium oxide \u2014 the calcium combines with oxygen from the air", false]], "q": "Molten calcium chloride (CaCl\u2082) is electrolysed. What is produced at the cathode?", "wrong_explanations": {"1": "Cl\u207b is NEGATIVE \u2014 it moves to the POSITIVE ANODE, not the cathode. The cathode attracts positive Ca\u00b2\u207a ions.", "2": "Electrolysis DOES decompose the compound \u2014 that is its purpose.", "3": "Electrolysis is done in an enclosed container \u2014 calcium doesn't react with air at this stage. The product is pure calcium metal."}}, {"opts": [["In the solid, Pb\u00b2\u207a and Br\u207b ions are fixed \u2014 they cannot move to carry charge. Melting gives the ions freedom to move.", true], ["Melting changes the chemical formula of lead bromide, making electrolysis possible.", false], ["The electrodes cannot penetrate a solid \u2014 they need a liquid to make contact.", false], ["Solid lead bromide doesn't contain ions \u2014 they form when it melts.", false]], "q": "Why must lead bromide be melted before it can be electrolysed?", "wrong_explanations": {"1": "Melting does NOT change the chemical formula \u2014 PbBr\u2082 is still PbBr\u2082 whether solid or molten.", "2": "In a proper setup, electrodes can contact a solid \u2014 but the solid still won't conduct electricity because the ions can't move.", "3": "Lead bromide is ionic in BOTH solid and molten states \u2014 Na\u207a and Cl\u207b (or Pb\u00b2\u207a and Br\u207b) ions exist in the solid too. They just can't move."}}], "CH": [{"opts": [["Calcium metal \u2014 Ca\u00b2\u207a ions are reduced at the negative cathode", true], ["Chlorine gas \u2014 Cl\u207b ions are discharged at the cathode", false], ["Calcium chloride \u2014 no decomposition occurs at the cathode", false], ["Calcium oxide \u2014 the calcium combines with oxygen from the air", false]], "q": "Molten calcium chloride (CaCl\u2082) is electrolysed. What is produced at the cathode?", "wrong_explanations": {"1": "Cl\u207b is NEGATIVE \u2014 it moves to the POSITIVE ANODE, not the cathode. The cathode attracts positive Ca\u00b2\u207a ions.", "2": "Electrolysis DOES decompose the compound \u2014 that is its purpose.", "3": "Electrolysis is done in an enclosed container \u2014 calcium doesn't react with air at this stage. The product is pure calcium metal."}}, {"opts": [["In the solid, Pb\u00b2\u207a and Br\u207b ions are fixed \u2014 they cannot move to carry charge. Melting gives the ions freedom to move.", true], ["Melting changes the chemical formula of lead bromide, making electrolysis possible.", false], ["The electrodes cannot penetrate a solid \u2014 they need a liquid to make contact.", false], ["Solid lead bromide doesn't contain ions \u2014 they form when it melts.", false]], "q": "Why must lead bromide be melted before it can be electrolysed?", "wrong_explanations": {"1": "Melting does NOT change the chemical formula \u2014 PbBr\u2082 is still PbBr\u2082 whether solid or molten.", "2": "In a proper setup, electrodes can contact a solid \u2014 but the solid still won't conduct electricity because the ions can't move.", "3": "Lead bromide is ionic in BOTH solid and molten states \u2014 Na\u207a and Cl\u207b (or Pb\u00b2\u207a and Br\u207b) ions exist in the solid too. They just can't move."}}], "TF": [{"opts": [["Calcium metal \u2014 Ca\u00b2\u207a ions are reduced at the negative cathode", true], ["Chlorine gas \u2014 Cl\u207b ions are discharged at the cathode", false], ["Calcium chloride \u2014 no decomposition occurs at the cathode", false], ["Calcium oxide \u2014 the calcium combines with oxygen from the air", false]], "q": "Molten calcium chloride (CaCl\u2082) is electrolysed. What is produced at the cathode?", "wrong_explanations": {"1": "Cl\u207b is NEGATIVE \u2014 it moves to the POSITIVE ANODE, not the cathode. The cathode attracts positive Ca\u00b2\u207a ions.", "2": "Electrolysis DOES decompose the compound \u2014 that is its purpose.", "3": "Electrolysis is done in an enclosed container \u2014 calcium doesn't react with air at this stage. The product is pure calcium metal."}}, {"opts": [["In the solid, Pb\u00b2\u207a and Br\u207b ions are fixed \u2014 they cannot move to carry charge. Melting gives the ions freedom to move.", true], ["Melting changes the chemical formula of lead bromide, making electrolysis possible.", false], ["The electrodes cannot penetrate a solid \u2014 they need a liquid to make contact.", false], ["Solid lead bromide doesn't contain ions \u2014 they form when it melts.", false]], "q": "Why must lead bromide be melted before it can be electrolysed?", "wrong_explanations": {"1": "Melting does NOT change the chemical formula \u2014 PbBr\u2082 is still PbBr\u2082 whether solid or molten.", "2": "In a proper setup, electrodes can contact a solid \u2014 but the solid still won't conduct electricity because the ions can't move.", "3": "Lead bromide is ionic in BOTH solid and molten states \u2014 Na\u207a and Cl\u207b (or Pb\u00b2\u207a and Br\u207b) ions exist in the solid too. They just can't move."}}], "TH": [{"opts": [["Calcium metal \u2014 Ca\u00b2\u207a ions are reduced at the negative cathode", true], ["Chlorine gas \u2014 Cl\u207b ions are discharged at the cathode", false], ["Calcium chloride \u2014 no decomposition occurs at the cathode", false], ["Calcium oxide \u2014 the calcium combines with oxygen from the air", false]], "q": "Molten calcium chloride (CaCl\u2082) is electrolysed. What is produced at the cathode?", "wrong_explanations": {"1": "Cl\u207b is NEGATIVE \u2014 it moves to the POSITIVE ANODE, not the cathode. The cathode attracts positive Ca\u00b2\u207a ions.", "2": "Electrolysis DOES decompose the compound \u2014 that is its purpose.", "3": "Electrolysis is done in an enclosed container \u2014 calcium doesn't react with air at this stage. The product is pure calcium metal."}}, {"opts": [["In the solid, Pb\u00b2\u207a and Br\u207b ions are fixed \u2014 they cannot move to carry charge. Melting gives the ions freedom to move.", true], ["Melting changes the chemical formula of lead bromide, making electrolysis possible.", false], ["The electrodes cannot penetrate a solid \u2014 they need a liquid to make contact.", false], ["Solid lead bromide doesn't contain ions \u2014 they form when it melts.", false]], "q": "Why must lead bromide be melted before it can be electrolysed?", "wrong_explanations": {"1": "Melting does NOT change the chemical formula \u2014 PbBr\u2082 is still PbBr\u2082 whether solid or molten.", "2": "In a proper setup, electrodes can contact a solid \u2014 but the solid still won't conduct electricity because the ions can't move.", "3": "Lead bromide is ionic in BOTH solid and molten states \u2014 Na\u207a and Cl\u207b (or Pb\u00b2\u207a and Br\u207b) ions exist in the solid too. They just can't move."}}]}, "rp": "RP4 (Chemistry) \u2014 Carry out electrolysis of lead(II) bromide. Observe products at each electrode. Safety: work in fume cupboard \u2014 bromine is toxic.", "summary": "Predict and explain the products of electrolysing molten ionic compounds.", "theory": [{"content": "When a MOLTEN ionic compound is electrolysed, the ONLY ions present are those from the compound itself.\n\nThis makes prediction simple:\nAt the CATHODE (negative): the POSITIVE METAL ION is discharged \u2192 metal is deposited.\nAt the ANODE (positive): the NEGATIVE NON-METAL ION is discharged \u2192 non-metal element (often a gas) is produced.\n\nExample \u2014 electrolysis of molten sodium chloride (NaCl):\nIons present: Na\u207a and Cl\u207b only.\nCathode: Na\u207a + e\u207b \u2192 Na (sodium metal produced \u2014 liquid, very reactive)\nAnode: 2Cl\u207b \u2192 Cl\u2082 + 2e\u207b (chlorine gas produced \u2014 yellow-green, toxic)\n\nExample \u2014 electrolysis of molten lead bromide (PbBr\u2082):\nIons present: Pb\u00b2\u207a and Br\u207b only.\nCathode: Pb\u00b2\u207a + 2e\u207b \u2192 Pb (lead metal deposited)\nAnode: 2Br\u207b \u2192 Br\u2082 + 2e\u207b (bromine liquid/vapour produced \u2014 brown)", "heading": "Products from Molten Ionic Compounds"}, {"content": "SOLID ionic compounds have ions FIXED in the lattice \u2014 they cannot move \u2192 no electrolysis possible.\nMOLTEN ionic compounds have ions FREE TO MOVE \u2192 electrolysis can occur.\n\nPractical considerations:\nMelting ionic compounds often requires very high temperatures.\nNaCl melts at 801\u00b0C \u2014 very high energy input needed.\nSpecial equipment and safety measures required.\nThis is why electrolysis is expensive for very reactive metal production.\n\nFor ALUMINIUM: the compound is DISSOLVED in molten cryolite (not just melted on its own) to lower the operating temperature from ~2050\u00b0C to ~950\u00b0C \u2014 still very high, but more practically manageable.", "heading": "Why Molten Rather Than Solid?"}, {"content": "Lead bromide is commonly used in school demonstrations:\n\nBefore melting: no conductivity \u2014 ions fixed in solid.\nAfter melting: circuit completes \u2014 ions free to move.\n\nCATHODE observations:\nGrey metallic liquid appears at the negative electrode.\nLead forms as liquid (above its melting point at these temperatures).\n\nANODE observations:\nReddish-brown bromine vapour produced at positive electrode.\nBromine is a brown liquid/red-brown vapour.\n\nOVERALL: PbBr\u2082(l) \u2192 Pb(l) + Br\u2082(g)\n\nNote: the solid lead bromide MUST be melted before any electrolysis occurs \u2014 a clear observation of why ions must be mobile.", "heading": "Observations During Electrolysis of Lead Bromide"}]};
